1	//! Saved views — named time-range + filter snapshots scoped to a
2	//! dashboard.
3	//!
4	//! Replaces `localStorage["xerj.views"]`.  Smaller surface than
5	//! dashboards: no etag concurrency (views are rarely co-edited), no
6	//! patch (clients DELETE-and-create instead).
7	
8	use axum::{
9	    extract::{Path, Query, State},
10	    response::Response,
11	    Json,
12	};
13	use serde::{Deserialize, Serialize};
14	use serde_json::{json, Value};
15	
16	use crate::auth::sessions::AuthSession;
17	use crate::error::{ConsoleApiError, ConsoleResult};
18	use crate::indices;
19	use crate::response::{created, no_content, ok};
20	use crate::state::ConsoleState;
21	use crate::time::now_iso;
22	
23	#[derive(Debug, Clone, Serialize, Deserialize)]
24	pub struct View {
25	    pub id: String,
26	    pub owner: String,
27	    #[serde(default = "default_org")]
28	    pub org_id: String,
29	    pub dashboard_id: String,
30	    pub name: String,
31	    #[serde(default)]
32	    pub time: Option<Value>,
33	    #[serde(default)]
34	    pub filters: Option<Value>,
35	    pub updated_at: String,
36	}
37	
38	fn default_org() -> String {
39	    "default".to_string()
40	}
41	
42	#[derive(Debug, Deserialize)]
43	pub struct ListQuery {
44	    pub dashboard: Option<String>,
45	}
46	
47	pub async fn list(
48	    State(state): State<ConsoleState>,
49	    sess: AuthSession,
50	    Query(q): Query<ListQuery>,
51	) -> ConsoleResult<Response> {
52	    let idx = state.engine.get_index(indices::VIEWS)?;
53	    let mut must: Vec<Value> = vec![json!({ "term": { "owner": sess.user.id } })];
54	    if let Some(dash) = q.dashboard {
55	        must.push(json!({ "term": { "dashboard_id": dash } }));
56	    }
57	    let body = json!({
58	        "query": { "bool": { "must": must } },
59	        "size": 200
60	    });
61	    let req = xerj_query::parser::parse_request(&body)
62	        .map_err(|e| ConsoleApiError::Internal(e.to_string()))?;
63	    let r = idx.search(&req).await?;
64	    let items: Vec<Value> = r.hits.into_iter().map(|h| h.source).collect();
65	    Ok(ok(json!({ "views": items, "total": items.len() }), None))
66	}
67	
68	#[derive(Debug, Deserialize)]
69	pub struct CreateBody {
70	    pub dashboard_id: String,
71	    pub name: String,
72	    #[serde(default)]
73	    pub time: Option<Value>,
74	    #[serde(default)]
75	    pub filters: Option<Value>,
76	}
77	
78	pub async fn create(
79	    State(state): State<ConsoleState>,
80	    sess: AuthSession,
81	    Json(body): Json<CreateBody>,
82	) -> ConsoleResult<Response> {
83	    let id = uuid::Uuid::new_v4().to_string();
84	    let view = View {
85	        id: id.clone(),
86	        owner: sess.user.id.clone(),
87	        org_id: default_org(),
88	        dashboard_id: body.dashboard_id,
89	        name: body.name,
90	        time: body.time,
91	        filters: body.filters,
92	        updated_at: now_iso(),
93	    };
94	    let idx = state.engine.get_index(indices::VIEWS)?;
95	    idx.create_document(id.clone(), serde_json::to_value(&view)?)
96	        .await?;
97	    let location = format!("/_xerj-console/api/v1/views/{id}");
98	    Ok(created(view, &location, None))
99	}
100	
101	pub async fn get_one(
102	    State(state): State<ConsoleState>,
103	    sess: AuthSession,
104	    Path(id): Path<String>,
105	) -> ConsoleResult<Response> {
106	    let view = read(&state, &id).await?;
107	    if view.owner != sess.user.id {
108	        return Err(ConsoleApiError::NotFound("view".into()));
109	    }
110	    Ok(ok(view, None))
111	}
112	
113	pub async fn delete(
114	    State(state): State<ConsoleState>,
115	    sess: AuthSession,
116	    Path(id): Path<String>,
117	) -> ConsoleResult<Response> {
118	    let view = read(&state, &id).await?;
119	    if view.owner != sess.user.id {
120	        return Err(ConsoleApiError::NotFound("view".into()));
121	    }
122	    let idx = state.engine.get_index(indices::VIEWS)?;
123	    // Same contract as `store::delete_passkey`: `Ok(false)` is already-absent
124	    // (idempotent), so only a refused write becomes an error. Swallowing
125	    // that error used to return 204 while the view stayed on disk.
126	    idx.delete_document(&id).await?;
127	    Ok(no_content())
128	}
129	
130	async fn read(state: &ConsoleState, id: &str) -> ConsoleResult<View> {
131	    let idx = state.engine.get_index(indices::VIEWS)?;
132	    let body = json!({
133	        "query": { "ids": { "values": [id] } },
134	        "size": 1
135	    });
136	    let req = xerj_query::parser::parse_request(&body)
137	        .map_err(|e| ConsoleApiError::Internal(e.to_string()))?;
138	    let r = idx.search(&req).await?;
139	    let hit = r
140	        .hits
141	        .into_iter()
142	        .next()
143	        .ok_or_else(|| ConsoleApiError::NotFound(format!("view {id}")))?;
144	    Ok(serde_json::from_value(hit.source)?)
145	}
