52	/// Where the guest page lives on the node. Must match the `url_path` the
53	/// server returns (`xerj-api::share::create_share`); the server's value wins
54	/// when it sends one.
55	const GUEST_PAGE_PATH: &str = "/_xerj-console/share";
56	/// Where a node listens unless told otherwise — the same default `xerj brain`
57	/// uses.
58	const DEFAULT_URL: &str = "http://localhost:9200";
59	/// How long `cloudflared` gets to print its hostname.
60	const TUNNEL_URL_TIMEOUT: Duration = Duration::from_secs(45);
61	/// After the hostname is known, how long to wait for the first edge
62	/// connection before printing the link anyway.
63	const TUNNEL_CONNECT_TIMEOUT: Duration = Duration::from_secs(20);
64	
65	pub fn run_cli() -> i32 {
66	    let args: Vec<String> = std::env::args().skip(2).collect();
67	    let cfg = match parse(args, std::env::var("XERJ_API_KEY").ok()) {
68	        Ok(Some(cfg)) => cfg,
69	        Ok(None) => {
70	            print_help();
71	            return 0;
72	        }
73	        Err(e) => {
74	            eprintln!("error: {e}\n");
75	            print_help();
76	            return 2;
77	        }
78	    };
79	    match run(cfg) {
80	        Ok(code) => code,
81	        Err(e) => {
82	            eprintln!("error: {e:#}");
83	            1
84	        }
85	    }
86	}
