205	/// `env_key` is the ambient `XERJ_API_KEY`, passed in so tests do not depend
206	/// on (or race over) the process environment.
207	fn parse(args: Vec<String>, env_key: Option<String>) -> Result<Option<ShareCfg>, String> {
208	    let mut it = args.into_iter();
209	    let mut target: Option<String> = None;
210	    let mut list = false;
211	    let mut revoke: Option<String> = None;
212	    let mut url = DEFAULT_URL.to_string();
213	    let mut data_dir: Option<PathBuf> = None;
214	    let mut api_key = env_key.filter(|s| !s.is_empty());
215	    let mut json = false;
216	    let mut create = CreateCfg {
217	        target: String::new(),
218	        force_index: false,
219	        brain: None,
220	        expires: None,
221	        max_claims: None,
222	        passcode: None,
223	        label: None,
224	        tunnel: false,
225	        keep: false,
226	        public_url: None,
227	    };
228	    // Which create-only flags were seen, so `--list --expires 1h` is an error
229	    // rather than a silently ignored flag.
230	    let mut create_flags: Vec<&'static str> = Vec::new();
231	
232	    while let Some(arg) = it.next() {
233	        match arg.as_str() {
234	            "--list" => list = true,
235	            "--revoke" => revoke = Some(it.next().ok_or("--revoke needs a share handle")?),
236	            "--expires" => {
237	                let spec = it.next().ok_or("--expires needs a value like 24h")?;
238	                let ms = xerj_api::share::parse_expires_in(&spec).ok_or_else(|| {
239	                    format!("--expires {spec}: use a number and a unit — 30m, 24h, 7d")
240	                })?;
241	                if !(xerj_api::share::MIN_EXPIRES_MS..=xerj_api::share::MAX_EXPIRES_MS)
242	                    .contains(&ms)
243	                {
244	                    return Err(format!("--expires {spec}: must be between 1s and 30d"));
245	                }
246	                create.expires = Some(spec);
247	                create_flags.push("--expires");
248	            }
249	            "--max-claims" => {
250	                let raw = it.next().ok_or("--max-claims needs a number")?;
251	                let n: u32 = raw
252	                    .parse()
253	                    .map_err(|_| format!("--max-claims {raw}: not a number"))?;
254	                if !(1..=xerj_api::share::MAX_MAX_CLAIMS).contains(&n) {
255	                    return Err(format!(
256	                        "--max-claims {n}: must be from 1 to {}",
257	                        xerj_api::share::MAX_MAX_CLAIMS
258	                    ));
259	                }
260	                create.max_claims = Some(n);
261	                create_flags.push("--max-claims");
262	            }
263	            "--passcode" => {
264	                let code = it.next().ok_or("--passcode needs a value")?;
265	                let n = code.trim().chars().count();
266	                if !(xerj_api::share::MIN_PASSCODE_CHARS..=xerj_api::share::MAX_PASSCODE_CHARS)
267	                    .contains(&n)
268	                {
269	                    return Err(format!(
270	                        "--passcode must be {}–{} characters",
271	                        xerj_api::share::MIN_PASSCODE_CHARS,
272	                        xerj_api::share::MAX_PASSCODE_CHARS
273	                    ));
274	                }
275	                create.passcode = Some(code.trim().to_string());
276	                create_flags.push("--passcode");
277	            }
278	            "--label" => {
279	                let label = it.next().ok_or("--label needs a value")?;
280	                if label.chars().count() > xerj_api::share::MAX_LABEL_CHARS {
281	                    return Err(format!(
282	                        "--label must be at most {} characters",
283	                        xerj_api::share::MAX_LABEL_CHARS
284	                    ));
285	                }
286	                create.label = Some(label);
287	                create_flags.push("--label");
288	            }
289	            "--brain" => {
290	                let name = it.next().ok_or("--brain needs a value")?;
291	                detect::validate_brain(&name)
292	                    .map_err(|reason| format!("--brain {name}: {reason}"))?;
293	                create.brain = Some(name);
294	                create_flags.push("--brain");
295	            }
296	            "--index" => {
297	                create.force_index = true;
298	                create_flags.push("--index");
299	            }
300	            "--tunnel" => {
301	                create.tunnel = true;
302	                create_flags.push("--tunnel");
303	            }
304	            "--keep" => {
305	                create.keep = true;
306	                create_flags.push("--keep");
307	            }
308	            "--public-url" => {
309	                let u = it.next().ok_or("--public-url needs a value")?;
310	                if !(u.starts_with("https://") || u.starts_with("http://")) {
311	                    return Err(format!(
312	                        "--public-url {u}: must start with https:// (or http://)"
313	                    ));
314	                }
315	                create.public_url = Some(u.trim_end_matches('/').to_string());
316	                create_flags.push("--public-url");
317	            }
318	            "--url" => {
319	                // Without a scheme the HTTP client fails before it connects,
320	                // and that used to be reported as "no xerj node answers" while
321	                // the node was up (review of PR #947).
322	                let u = it.next().ok_or("--url needs a value")?;
323	                if !(u.starts_with("http://") || u.starts_with("https://")) {
324	                    return Err(format!(
325	                        "--url {u}: include the scheme — for example http://{u}"
326	                    ));
327	                }
328	                url = u;
329	            }
330	            "--data-dir" => {
331	                data_dir = Some(PathBuf::from(it.next().ok_or("--data-dir needs a value")?))
332	            }
333	            "--api-key" => api_key = Some(it.next().ok_or("--api-key needs a value")?),
334	            "--json" => json = true,
335	            // Read out of band by `xerj_common::feedback`; accepted here so it
336	            // is not "unknown".
337	            xerj_common::feedback::DISABLE_FLAG => {}
338	            "--help" | "-h" => return Ok(None),
339	            other if !other.starts_with('-') && target.is_none() => {
340	                target = Some(other.to_string())
341	            }
342	            other => return Err(format!("unknown argument: {other}")),
343	        }
344	    }
345	
346	    let common = Common {
347	        url: url.trim_end_matches('/').to_string(),
348	        data_dir,
349	        api_key,
350	        json,
351	    };
352	
353	    let picked = [list, revoke.is_some(), target.is_some()]
354	        .iter()
355	        .filter(|b| **b)
356	        .count();
357	    if picked == 0 {
358	        return Ok(None); // nothing asked for → help, like `xerj brain`
359	    }
360	    if picked > 1 {
361	        return Err("choose one: a target to share, --list, or --revoke <handle>".into());
362	    }
363	    if (list || revoke.is_some()) && !create_flags.is_empty() {
364	        return Err(format!(
365	            "{} only applies when creating a share",
366	            create_flags.join(", ")
367	        ));
368	    }
369	    if create.keep && !create.tunnel {
370	        return Err("--keep only applies with --tunnel".into());
371	    }
372	    if create.tunnel && create.public_url.is_some() {
373	        return Err(
374	            "--tunnel and --public-url are two answers to the same question; pick one".into(),
375	        );
376	    }
377	
378	    let action = if list {
379	        Action::List
380	    } else if let Some(handle) = revoke {
381	        let handle = handle.trim().to_string();
382	        // Exactly the 12-hex handle. The 32-hex share id from a link would
383	        // work on the server, but it would travel in the DELETE's request
384	        // path, and the docs say the CLI never puts a share id in a URL.
385	        let hex = handle.chars().all(|c| c.is_ascii_hexdigit());
386	        if handle.len() == 32 && hex {
387	            // Not echoed: the error line may end up in a terminal log.
388	            return Err(
389	                "--revoke <share id>: that is the share id from the link, which is \
390	                 never sent in a URL — revoke by the handle `xerj share --list` prints"
391	                    .into(),
392	            );
393	        }
394	        if handle.len() != 12 || !hex {
395	            return Err(format!(
396	                "--revoke {handle}: a share handle is the 12 hex characters `xerj share \
397	                 --list` prints"
398	            ));
399	        }
400	        Action::Revoke(handle)
401	    } else {
402	        create.target = target.unwrap_or_default();
403	        Action::Create(create)
404	    };
405	    Ok(Some(ShareCfg { common, action }))
406	}
