412	/// What the positional argument names.
413	#[derive(Debug, Clone, PartialEq, Eq)]
414	pub enum Target {
415	    /// One or more concrete index names.
416	    Indices(Vec<String>),
417	    /// A folder `xerj brain` indexed.
418	    Folder(PathBuf),
419	}
420	
421	/// Decide what `arg` names. `is_dir` is injected so the rule is testable
422	/// without a filesystem.
423	///
424	/// An existing directory wins unless `--index` was passed: the command is
425	/// documented as "share the folder you gave `xerj brain`", and printing what
426	/// the folder resolved to (see [`run`]) makes a wrong guess visible before
427	/// anything is sent to anyone. Something that *looks* like a path but is not a
428	/// directory is an error, never an index name — `xerj share ./nots` must not
429	/// turn into a request for an index called `./nots`.
430	fn classify_target(
431	    arg: &str,
432	    force_index: bool,
433	    is_dir: impl Fn(&Path) -> bool,
434	) -> Result<Target, String> {
435	    let arg = arg.trim();
436	    if arg.is_empty() {
437	        return Err("name an index or a folder to share".into());
438	    }
439	    let pathish =
440	        arg.contains('/') || arg.contains('\\') || arg.starts_with('.') || arg.starts_with('~');
441	    if force_index {
442	        if pathish {
443	            return Err(format!("--index {arg}: that is a path, not an index name"));
444	        }
445	    } else {
446	        if is_dir(Path::new(arg)) {
447	            return Ok(Target::Folder(PathBuf::from(arg)));
448	        }
449	        if pathish {
450	            return Err(format!(
451	                "{arg} is not a folder here. Pass the folder you gave `xerj brain`, or an \
452	                 index name (see `xerj autoindex map`)"
453	            ));
454	        }
455	    }
456	    let indices: Vec<String> = arg
457	        .split(',')
458	        .map(str::trim)
459	        .filter(|s| !s.is_empty())
460	        .map(String::from)
461	        .collect();
462	    if indices.is_empty() {
463	        return Err("name an index or a folder to share".into());
464	    }
465	    Ok(Target::Indices(indices))
466	}
