505	/// The host part of an `http(s)://host[:port]/…` URL, brackets kept.
506	fn url_host(url: &str) -> Option<&str> {
507	    let rest = url
508	        .strip_prefix("http://")
509	        .or_else(|| url.strip_prefix("https://"))?;
510	    let hostport = rest.split(['/', '?', '#']).next().unwrap_or(rest);
511	    let host = match hostport.strip_prefix('[') {
512	        // [::1]:9200
513	        Some(v6) => v6.split(']').next().unwrap_or(v6),
514	        None => hostport.rsplit_once(':').map_or(hostport, |(h, _)| h),
515	    };
516	    (!host.is_empty()).then_some(host)
517	}
518	
519	/// Does `url` name this machine and nothing else?
520	fn is_loopback_url(url: &str) -> bool {
521	    match url_host(url) {
522	        Some("localhost") => true,
523	        Some(host) => host
524	            .parse::<std::net::IpAddr>()
525	            .is_ok_and(|ip| ip.is_loopback()),
526	        None => false,
527	    }
528	}
