543	/// The link a guest opens. The share id rides in the **fragment**: a browser
544	/// never sends a fragment to the server, so the page request carries no id and
545	/// neither does any `Referer`. The page's own script then sends the id in the
546	/// **body** of the claim `POST` (`/_share/claim`) — never in a path, which is
547	/// what an access log, a reverse proxy and a tunnel's edge would record.
548	pub fn guest_link(base_url: &str, url_path: Option<&str>, share_id: &str) -> String {
549	    let base = base_url.trim_end_matches('/');
550	    match url_path {
551	        // The node's own path wins — but only a console path whose fragment is
552	        // exactly this share id and that carries no query string. Anything
553	        // else falls back to the path this build knows.
554	        Some(p)
555	            if p.starts_with("/_xerj-console/")
556	                && !p.contains('?')
557	                && p.split_once('#').map(|(_, frag)| frag) == Some(share_id) =>
558	        {
559	            format!("{base}{p}")
560	        }
561	        _ => format!("{base}{GUEST_PAGE_PATH}#{share_id}"),
562	    }
563	}
