565	/// Pull the public hostname out of one line of `cloudflared` output. The
566	/// banner wraps it in a box (`|  https://x-y-z.trycloudflare.com   |`); the
567	/// URL itself has no whitespace. Only a `trycloudflare.com` host counts —
568	/// the log also mentions `https://www.cloudflare.com/website-terms/` and
569	/// `https://developers.cloudflare.com/…`, which are not tunnels.
570	fn parse_tunnel_url(line: &str) -> Option<String> {
571	    let mut rest = line;
572	    while let Some(at) = rest.find("https://") {
573	        let tail = &rest[at..];
574	        let end = tail
575	            .find(|c: char| c.is_whitespace() || c == '|' || c == '"' || c == '\'')
576	            .unwrap_or(tail.len());
577	        let url = tail[..end].trim_end_matches(['/', '.', ',']);
578	        let host = url.trim_start_matches("https://");
579	        let host = host.split('/').next().unwrap_or(host);
580	        if host.ends_with(".trycloudflare.com")
581	            && host.len() > ".trycloudflare.com".len()
582	            && host
583	                .chars()
584	                .all(|c| c.is_ascii_alphanumeric() || c == '-' || c == '.')
585	        {
586	            return Some(format!("https://{host}"));
587	        }
588	        rest = &tail[8..];
589	    }
590	    None
591	}
