598	/// (host, port) of a plain-http node URL — the only kind `--tunnel` fronts.
599	fn local_http_origin(url: &str) -> Result<(String, u16), String> {
600	    let Some(rest) = url.strip_prefix("http://") else {
601	        return Err(format!(
602	            "--tunnel fronts a plain-http node on this machine (the default); {url} is not \
603	             one. For a TLS node, run your own `cloudflared tunnel --url {url} \
604	             --no-tls-verify` and pass its address as --public-url"
605	        ));
606	    };
607	    let hostport = rest.split('/').next().unwrap_or(rest);
608	    let (host, port) = match hostport.rsplit_once(':') {
609	        Some((h, p)) => (
610	            h.to_string(),
611	            p.parse::<u16>()
612	                .map_err(|_| format!("invalid port in --url {url}"))?,
613	        ),
614	        None => (hostport.to_string(), 9200),
615	    };
616	    if !matches!(host.as_str(), "localhost" | "127.0.0.1" | "[::1]" | "::1") {
617	        return Err(format!(
618	            "--tunnel exposes a node on THIS machine; {url} is somewhere else. Run \
619	             `xerj share --tunnel` on the machine that holds the data"
620	        ));
621	    }
622	    Ok((host, port))
623	}
