706	
707	fn run(cfg: ShareCfg) -> Result<i32> {
708	    let common = &cfg.common;
709	
710	    // 1. Is anything there, and is it enforcing anything? An unauthenticated
711	    //    `GET /` answers 200 only on an open node.
712	    let anon = Es::new(&common.url, None)?;
713	    match anon.get_status("/") {
714	        Ok(200) => bail!("{}", open_mode_refusal(&common.url)),
715	        Ok(401) | Ok(403) => {}
716	        Ok(status) => bail!(
717	            "something answers at {} but it does not look like a xerj node (GET / → HTTP \
718	             {status}). Point --url at your node",
719	            common.url
720	        ),
721	        Err(_) => bail!(
722	            "no xerj node answers at {}. Start one first — `xerj brain <folder>` boots a \
723	             node and indexes the folder — or pass --url",
724	            common.url
725	        ),
726	    }
727	
728	    // 2. The admin key.
729	    let (api_key, key_path) = resolve_api_key(common);
730	    let Some(api_key) = api_key else {
731	        bail!(
732	            "no admin key. Shares are managed with the node's admin key: pass --api-key, set \
733	             XERJ_API_KEY, or point --data-dir at the node's data directory (looked for {})",
734	            key_path.display()
735	        );
736	    };
737	    let es = Es::new(&common.url, Some(api_key))?;
738	
739	    match &cfg.action {
740	        Action::List => list(&es, common),
741	        Action::Revoke(handle) => revoke(&es, common, handle),
742	        Action::Create(create) => create_share(&es, common, create),
743	    }
744	}
