746	/// Turn a non-2xx from `/_share` into words.
747	fn explain(status: u16, body: &Value, common: &Common) -> anyhow::Error {
748	    let reason = body
749	        .pointer("/error/reason")
750	        .and_then(Value::as_str)
751	        .unwrap_or("");
752	    match status {
753	        401 => anyhow!(
754	            "the node at {} rejected the key. Shares need the node's ADMIN key — the one in \
755	             <data_dir>/admin.key",
756	            common.url
757	        ),
758	        403 => anyhow!(
759	            "that key is not the admin key. A scoped or minted key cannot create, list or \
760	             revoke shares — otherwise it could widen its own reach. Use the key in \
761	             <data_dir>/admin.key"
762	        ),
763	        409 => anyhow!("{}", open_mode_refusal(&common.url)),
764	        404 if !reason.is_empty() => anyhow!("{reason}"),
765	        404 | 405 => anyhow!(
766	            "the node at {} has no share links (`/_share` is not there) — it is an older \
767	             xerj. Upgrade the node, then run this again",
768	            common.url
769	        ),
770	        _ if !reason.is_empty() => anyhow!("{reason} (HTTP {status})"),
771	        _ => anyhow!(
772	            "unexpected HTTP {status} from {}/_share: {body}",
773	            common.url
774	        ),
775	    }
776	}
