778	fn list(es: &Es, common: &Common) -> Result<i32> {
779	    let (status, body) = es.request_json("GET", "/_share", None)?;
780	    if status != 200 {
781	        return Err(explain(status, &body, common));
782	    }
783	    if common.json {
784	        println!("{}", serde_json::to_string_pretty(&body)?);
785	        return Ok(0);
786	    }
787	    let shares = body
788	        .get("shares")
789	        .and_then(Value::as_array)
790	        .cloned()
791	        .unwrap_or_default();
792	    if shares.is_empty() {
793	        println!("no shares on this node. Create one: xerj share <index|folder>");
794	        return Ok(0);
795	    }
796	    println!(
797	        "{:<14} {:<10} {:<8} {:<22} {:<28} LABEL",
798	        "HANDLE", "STATUS", "CLAIMS", "EXPIRES", "INDEX"
799	    );
800	    for s in &shares {
801	        let g = |k: &str| s.get(k).and_then(Value::as_str).unwrap_or("-").to_string();
802	        let claims = format!(
803	            "{}/{}",
804	            s.get("claims").and_then(Value::as_u64).unwrap_or(0),
805	            s.get("max_claims").and_then(Value::as_u64).unwrap_or(0)
806	        );
807	        println!(
808	            "{:<14} {:<10} {:<8} {:<22} {:<28} {}",
809	            g("handle"),
810	            g("status"),
811	            claims,
812	            g("expires_at"),
813	            g("index"),
814	            g("label")
815	        );
816	    }
817	    println!(
818	        "\nrevoke one: xerj share --revoke <HANDLE>{}",
819	        connection_args(common)
820	    );
821	    Ok(0)
822	}
