824	fn revoke(es: &Es, common: &Common, handle: &str) -> Result<i32> {
825	    let (status, body) = es.request_json("DELETE", &format!("/_share/{handle}"), None)?;
826	    if status == 404 {
827	        bail!("no share with handle {handle} on this node (see `xerj share --list`)");
828	    }
829	    if status != 200 {
830	        return Err(explain(status, &body, common));
831	    }
832	    if common.json {
833	        println!("{}", serde_json::to_string_pretty(&body)?);
834	        return Ok(0);
835	    }
836	    let n = body
837	        .get("keys_invalidated")
838	        .and_then(Value::as_u64)
839	        .unwrap_or(0);
840	    println!(
841	        "✓ share {handle} revoked — {n} guest key{} invalidated. Anyone who had opened it \
842	         loses access on their next request.",
843	        if n == 1 { "" } else { "s" }
844	    );
845	    Ok(0)
846	}
