958	fn create_share(es: &Es, common: &Common, create: &CreateCfg) -> Result<i32> {
959	    let resolved = resolve_target(es, common, create)?;
960	    if let Some(how) = &resolved.how {
961	        eprintln!("sharing {how}");
962	    }
963	
964	    // The tunnel comes up BEFORE the share exists, so a link is never printed
965	    // for an address that is not there, and a tunnel that cannot start costs
966	    // nothing but a message.
967	    let mut tunnel: Option<Tunnel> = None;
968	    let mut tunnel_note: Option<String> = None;
969	    // Listening before the tunnel exists — see `Interrupts`.
970	    let interrupts = create.tunnel.then(Interrupts::listen);
971	    if create.tunnel {
972	        let (_, port) = local_http_origin(&common.url).map_err(|e| anyhow!(e))?;
973	        match find_cloudflared() {
974	            None => {
975	                tunnel_note = Some(format!(
976	                    "--tunnel needs `cloudflared`, which is not installed (looked on PATH and \
977	                     in ~/.local/bin).\n{}\n  then run this command again. Until then the \
978	                     link above only works on this machine.",
979	                    cloudflared_install_help()
980	                ));
981	            }
982	            Some(bin) => {
983	                eprintln!("opening a tunnel with {} …", bin.display());
984	                let opened = Tunnel::open(
985	                    &bin,
986	                    port,
987	                    interrupts.as_ref().expect("listening when --tunnel is set"),
988	                );
989	                match opened {
990	                    Ok(t) => tunnel = Some(t),
991	                    Err(OpenError::Interrupted(why)) => {
992	                        eprintln!("{why} before the tunnel was up — nothing was shared.");
993	                        return Ok(130);
994	                    }
995	                    Err(OpenError::Failed(e)) => {
996	                        tunnel_note = Some(format!(
997	                            "the tunnel did not come up: {e:#}\n  the link above only works on \
998	                             this machine."
999	                        ))
1000	                    }
1001	                }
1002	            }
1003	        }
1004	    }
1005	
1006	    let mut body = json!({ "index": resolved.indices });
1007	    if let Some(b) = &resolved.brain {
1008	        body["brain"] = json!(b);
1009	    }
1010	    if let Some(e) = &create.expires {
1011	        body["expires_in"] = json!(e);
1012	    }
1013	    if let Some(n) = create.max_claims {
1014	        body["max_claims"] = json!(n);
1015	    }
1016	    if let Some(p) = &create.passcode {
1017	        body["passcode"] = json!(p);
1018	    }
1019	    if let Some(l) = &create.label {
1020	        body["label"] = json!(l);
1021	    }
1022	    let (status, resp) = es.request_json("POST", "/_share", Some(&body))?;
1023	    if status != 200 {
1024	        return Err(explain(status, &resp, common));
1025	    }
1026	    let share_id = resp
1027	        .get("share_id")
1028	        .and_then(Value::as_str)
1029	        .context("the node's response carries no share_id")?;
1030	    let handle = resp.get("handle").and_then(Value::as_str).unwrap_or("");
1031	    let url_path = resp.get("url_path").and_then(Value::as_str);
1032	
1033	    let base = tunnel
1034	        .as_ref()
1035	        .map(|t| t.public_url.clone())
1036	        .or_else(|| create.public_url.clone())
1037	        .unwrap_or_else(|| common.url.clone());
1038	    let link = guest_link(&base, url_path, share_id);
