1143	/// `arg` as one shell word, for a command the owner is meant to paste.
1144	///
1145	/// `xerj brain "case files"` printed `xerj share /…/case files --url …`, and
1146	/// pasting it failed with `unknown argument: files` (review of PR #947). An
1147	/// argument made only of characters no shell treats specially is left alone,
1148	/// so the common case still reads cleanly; anything else is quoted — single
1149	/// quotes on unix (`'` itself as `'\''`), double quotes on Windows, where
1150	/// `cmd.exe` and PowerShell both accept them around a path.
1151	pub(crate) fn sh_quote(arg: &str) -> String {
1152	    let plain = !arg.is_empty()
1153	        && arg.chars().all(|c| {
1154	            c.is_ascii_alphanumeric()
1155	                || matches!(c, '_' | '-' | '.' | '/' | ':' | ',' | '+' | '=' | '@' | '%')
1156	        });
1157	    if plain {
1158	        return arg.to_string();
1159	    }
1160	    if cfg!(windows) {
1161	        // A Windows path legitimately holds `\` and `:`; neither needs more
1162	        // than the surrounding quotes.
1163	        let bare_ok = !arg.is_empty()
1164	            && arg.chars().all(|c| {
1165	                c.is_ascii_alphanumeric() || matches!(c, '_' | '-' | '.' | '/' | '\\' | ':')
1166	            });
1167	        return if bare_ok {
1168	            arg.to_string()
1169	        } else {
1170	            format!("\"{}\"", arg.replace('"', "\\\""))
1171	        };
1172	    }
1173	    format!("'{}'", arg.replace('\'', "'\\''"))
1174	}
