1298	enum TunnelEvent {
1299	    Url(String),
1300	    Connected,
1301	    Exited,
1302	}
1303	
1304	/// Ctrl-C (and, on unix, SIGTERM / SIGHUP) as a channel.
1305	///
1306	/// Installed BEFORE `cloudflared` is spawned. The tunnel runs in its own
1307	/// process group so that it is closed by us, in order; the price is that a
1308	/// signal which kills this command by default action would orphan it. With the
1309	/// listener in place first, there is no window in which that can happen.
1310	///
1311	/// `xerj share` runs inside the binary's tokio runtime (on a blocking thread),
1312	/// so the portable signal futures are available — no handler of our own, and
1313	/// Ctrl-C works on Windows.
1314	struct Interrupts(mpsc::Receiver<&'static str>);
1315	
1316	impl Interrupts {
1317	    fn listen() -> Self {
1318	        let (tx, rx) = mpsc::channel::<&'static str>();
1319	        if let Ok(handle) = tokio::runtime::Handle::try_current() {
1320	            let tx_c = tx.clone();
1321	            handle.spawn(async move {
1322	                if tokio::signal::ctrl_c().await.is_ok() {
1323	                    let _ = tx_c.send("Ctrl-C");
1324	                }
1325	            });
1326	            #[cfg(unix)]
1327	            for (kind, name) in [
1328	                (tokio::signal::unix::SignalKind::terminate(), "SIGTERM"),
1329	                (tokio::signal::unix::SignalKind::hangup(), "terminal closed"),
1330	            ] {
1331	                let tx_s = tx.clone();
1332	                handle.spawn(async move {
1333	                    if let Ok(mut sig) = tokio::signal::unix::signal(kind) {
1334	                        if sig.recv().await.is_some() {
1335	                            let _ = tx_s.send(name);
1336	                        }
1337	                    }
1338	                });
1339	            }
1340	        }
1341	        Interrupts(rx)
1342	    }
1343	
1344	    fn fired(&self) -> Option<&'static str> {
1345	        self.0.try_recv().ok()
1346	    }
1347	}
