1356	/// The last lines `cloudflared` wrote. Its output is not shown while it works
1357	/// — it is a wall of connection chatter — but when it dies on its own those
1358	/// lines are the only explanation there is, and the first cut threw them away:
1359	/// the owner saw "cloudflared stopped" and a revoked share, and nothing else
1360	/// (review of PR #947, a real quick tunnel that dropped after two minutes).
1361	type TunnelLog = std::sync::Arc<std::sync::Mutex<std::collections::VecDeque<String>>>;
1362	/// How many of them are kept.
1363	const TUNNEL_LOG_LINES: usize = 20;
1364	
1365	/// `\n  cloudflared's last lines:\n    …` — or nothing, if it never wrote any.
1366	fn tunnel_log_tail(log: &TunnelLog) -> String {
1367	    let lines = match log.lock() {
1368	        Ok(l) => l,
1369	        Err(poisoned) => poisoned.into_inner(),
1370	    };
1371	    if lines.is_empty() {
1372	        return String::new();
1373	    }
1374	    let mut out = String::from("\n  cloudflared's last lines:");
1375	    for line in lines.iter() {
1376	        out.push_str("\n    ");
1377	        out.push_str(line);
1378	    }
1379	    out
1380	}
