1957	    /// Review of PR #947 (blocker): under `--tunnel` the banner said "the
1958	    /// guest's browser reads from this node" and never said "Cloudflare",
1959	    /// while every byte — passcode and guest key included — went through
1960	    /// Cloudflare's TLS termination. The owner reads this banner, not the docs,
1961	    /// in the second before sending the link.
1962	    #[test]
1963	    fn a_tunnel_link_says_cloudflare_can_read_the_traffic() {
1964	        let out = banner(
1965	            "https://a-b-c.trycloudflare.com/_xerj-console/share#id",
1966	            Reach::CloudflareTunnel,
1967	            DEFAULT_URL,
1968	        );
1969	        let flat = out.split_whitespace().collect::<Vec<_>>().join(" ");
1970	        assert!(flat.contains("goes through Cloudflare"), "{out}");
1971	        assert!(flat.contains("ends TLS at Cloudflare"), "{out}");
1972	        for crosses in [
1973	            "the passcode",
1974	            "the guest's key",
1975	            "every document the guest opens",
1976	        ] {
1977	            assert!(flat.contains(crosses), "must name {crosses:?}: {out}");
1978	        }
1979	        assert!(
1980	            flat.contains("--public-url"),
1981	            "must name the alternative: {out}"
1982	        );
1983	        // What Cloudflare keeps is Cloudflare's business; the notice does not
1984	        // promise anything about it. "nothing is uploaded or stored elsewhere"
1985	        // sat one line above the notice and promised exactly that, which is the
1986	        // retention claim f152538f removed from the notice itself.
1987	        assert!(!flat.contains("stored there"), "{out}");
1988	        for retention in ["or stored", "stored anywhere", "stored elsewhere"] {
1989	            assert!(
1990	                !flat.contains(retention),
1991	                "the banner promises what a third party retains ({retention:?}): {out}"
1992	            );
1993	        }
1994	        assert!(
1995	            !flat.contains("browser reads from this node"),
1996	            "in tunnel mode the browser reads from Cloudflare: {out}"
1997	        );
1998	        assert!(flat.contains("stay on this machine"), "{out}");
1999	        assert!(out.lines().all(|l| l.chars().count() <= 100), "{out}");
2000	        // No other mode mentions a third party that is not there.
2001	        let local = banner(
2002	            "http://localhost:9200/_xerj-console/share#id",
2003	            Reach::Loopback,
2004	            DEFAULT_URL,
2005	        );
2006	        assert!(!local.contains("ends TLS at Cloudflare"), "{local}");
2007	        assert!(local.contains("browser reads from this node"), "{local}");
2008	        // Behind --public-url the browser talks to whatever serves that
2009	        // address (a reverse proxy, maybe a CDN), so the banner does not say
2010	        // it reads from this node — it says who can read the traffic.
2011	        let public = banner(
2012	            "https://files.example.org/_xerj-console/share#id",
2013	            Reach::PublicUrl,
