1	// ============================================================
2	// XERJ Console — safe DOM construction
3	//
4	// The corpus home and the reader show OTHER PEOPLE'S DOCUMENTS: an email
5	// subject, an attachment filename, a PDF page, a highlight fragment, a graph
6	// node title. Every one of those strings is attacker-controlled (anyone can
7	// mail you `<img src=x onerror=…>` as a subject), and in guest mode the
8	// viewer's API key sits in sessionStorage on this origin — one script
9	// execution is key theft.
10	//
11	// The rest of the console builds HTML strings and relies on `esc()` at every
12	// interpolation. That is correct only while nobody ever forgets one. This
13	// module removes the HTML parser from the path instead:
14	//
15	//   h(tag, attrs, ...children)   a plain-data node. Children are nodes or
16	//                                STRINGS; a string is always text.
17	//   mount(container, nodes)      builds real DOM with createElement /
18	//                                createTextNode / setAttribute only.
19	//
20	// Guarantees, by construction rather than by discipline:
21	//   • no document string is ever parsed as HTML — this file, and everything
22	//     that renders through it, contains no markup-parsing sink at all
23	//     (test/safe-dom.test.mjs greps the sources for the full sink list);
24	//   • tags come from TAGS and attribute names from ATTRS — both closed
25	//     lists, and both are code constants, never data. An unknown tag or
26	//     attribute THROWS, so a typo (or someone "just adding onclick") fails
27	//     the tests instead of shipping;
28	//   • there is no `style`, no `src`, no `srcset`, no `action`, no `on*`;
29	//   • an `href` is kept only when it is an in-app hash route (`#/…`).
30	//     `javascript:`, `data:`, `vbscript:`, `//evil`, `https://…`, a leading
31	//     space or control character — all dropped, leaving an inert <a>. The
32	//     reader never links out: a URL found in a document is shown as text.
33	//
34	// `h` and the helpers are pure (no DOM), so render functions are testable
35	// under node; `mount` needs a Document and is exercised in a real browser
36	// (test/browser/).
37	// ============================================================
38	
39	/** Elements a render function may create. Nothing that loads a resource,
40	 *  runs script, or submits anywhere. */
41	export const TAGS = new Set([
42	  'div', 'span', 'p', 'a', 'h1', 'h2', 'h3', 'h4', 'ul', 'ol', 'li',
43	  'pre', 'code', 'mark', 'article', 'section', 'header', 'footer', 'nav',
44	  'button', 'b', 'strong', 'em', 'small', 'dl', 'dt', 'dd', 'br', 'hr',
45	  'label', 'input', 'select', 'option', 'time',
46	  // The only interactive element added for the knowledge surface: a
47	  // disclosure. It collapses/expands content the browser itself — no
48	  // script, no focus behaviour to get wrong, nothing loads.
49	  'details', 'summary',
50	]);
51	
52	/** Attribute names a render function may set (plus `data-*` / `aria-*`). */
53	export const ATTRS = new Set([
54	  'class', 'href', 'title', 'id', 'role', 'tabindex', 'type', 'name',
55	  'value', 'placeholder', 'for', 'disabled', 'selected', 'autocomplete',
56	  'spellcheck', 'datetime', 'hidden',
57	]);
58	
59	const INPUT_TYPES = new Set(['text', 'search']);
60	const BUTTON_TYPES = new Set(['button']);
61	
62	/** Is this attribute name allowed? `on*` can never pass: it is not in ATTRS
63	 *  and does not start with `data-` / `aria-`. */
64	export function attrAllowed(name) {
65	  if (typeof name !== 'string') return false;
66	  if (ATTRS.has(name)) return true;
67	  return /^(data|aria)-[a-z0-9-]+$/.test(name);
68	}
69	
70	function hasControlChar(s) {
71	  for (let i = 0; i < s.length; i++) {
72	    const c = s.charCodeAt(i);
73	    if (c < 0x20 || c === 0x7f) return true;
74	  }
75	  return false;
76	}
77	
78	/**
79	 * The only hrefs the console renders from data: in-app hash routes.
80	 * Returns the href when safe, null otherwise.
81	 */
82	export function safeHref(v) {
83	  if (typeof v !== 'string') return null;
84	  // `#/` exactly at position 0 — no leading whitespace/control characters
85	  // (browsers strip those before resolving a scheme) and no scheme at all.
86	  if (!v.startsWith('#/')) return null;
87	  // A fragment cannot change the document's origin or scheme, but keep
88	  // control characters out of attributes on principle.
89	  if (hasControlChar(v)) return null;
90	  return v;
91	}
92	
93	/** Build a node. `attrs` may be null. Falsy children are skipped; arrays are
94	 *  flattened; anything that is not a node becomes TEXT. */
95	export function h(tag, attrs, ...children) {
96	  if (!TAGS.has(tag)) throw new Error(`safe-dom: tag <${String(tag)}> is not allowed`);
97	  const a = {};
98	  for (const [k, v] of Object.entries(attrs || {})) {
99	    if (v == null || v === false) continue;
100	    if (!attrAllowed(k)) throw new Error(`safe-dom: attribute "${k}" is not allowed`);
101	    // An href must already BE a string: coercing first would let an object
102	    // with a crafted toString() choose the URL.
103	    if (k === 'href' && typeof v !== 'string') continue;
104	    a[k] = v === true ? '' : String(v);
105	  }
106	  if (tag === 'input' && !INPUT_TYPES.has(a.type || 'text')) {
107	    throw new Error(`safe-dom: <input type="${a.type}"> is not allowed`);
108	  }
109	  if (tag === 'button') {
110	    if (a.type && !BUTTON_TYPES.has(a.type)) throw new Error(`safe-dom: <button type="${a.type}"> is not allowed`);
111	    a.type = 'button';
112	  }
113	  if ('href' in a) {
114	    const ok = safeHref(a.href);
115	    if (ok == null) delete a.href; else a.href = ok;
116	  }
117	  const c = [];
118	  const push = (x) => {
119	    if (x == null || x === false || x === true || x === '') return;
120	    if (Array.isArray(x)) { x.forEach(push); return; }
121	    if (isNode(x)) { c.push(x); return; }
122	    c.push(String(x));
123	  };
124	  children.forEach(push);
125	  return { $: 'node', tag, attrs: a, children: c };
126	}
127	
128	export function isNode(x) {
129	  return !!x && typeof x === 'object' && x.$ === 'node' && typeof x.tag === 'string';
130	}
131	
132	/** All text under a node (or list), concatenated — what a person reads. */
133	export function textOf(node) {
134	  if (node == null) return '';
135	  if (Array.isArray(node)) return node.map(textOf).join('');
136	  if (typeof node === 'string') return node;
137	  if (!isNode(node)) return '';
138	  return node.children.map(textOf).join('');
139	}
140	
141	/** Depth-first visit of every element node. */
142	export function walk(node, fn) {
143	  if (Array.isArray(node)) { node.forEach((n) => walk(n, fn)); return; }
144	  if (!isNode(node)) return;
145	  fn(node);
146	  node.children.forEach((c) => walk(c, fn));
147	}
148	
149	/** Every element node matching `pred`, in document order. */
150	export function findAll(node, pred) {
151	  const out = [];
152	  walk(node, (n) => { if (pred(n)) out.push(n); });
153	  return out;
154	}
155	
156	// ----- highlights -----------------------------------------------------
157	
158	// The reader asks the engine to wrap matches in these two private-use
159	// characters (U+E000 / U+E001) instead of `<em>`/`</em>`. A highlight
160	// fragment is raw document text with the markers spliced in — the engine does
161	// NOT HTML-escape it — so it must never reach an HTML parser. We split on the
162	// markers and emit text + <mark> elements. A document that itself contains
163	// the marker characters can at worst cause a stray <mark>; it cannot
164	// introduce markup.
165	export const HL_PRE = String.fromCharCode(0xe000);
166	export const HL_POST = String.fromCharCode(0xe001);
167	
168	/** The `highlight` block to send with a search so fragments use the markers. */
169	export function highlightRequest(fields, { fragmentSize = 160, fragments = 2 } = {}) {
170	  const f = {};
171	  for (const name of fields || []) {
172	    if (typeof name === 'string' && name) f[name] = { fragment_size: fragmentSize, number_of_fragments: fragments };
173	  }
174	  // Both spellings, because the engine has two request parsers: the ES-compat
175	  // route (a guest) reads the plural arrays, the console's search proxy (an
176	  // operator) reads the singular strings and ignores the rest. Sending only
177	  // one silently falls back to `<em>` on the other route
178	  // (pinned by xerj-console-api/tests/reader_proxy.rs).
179	  return { pre_tags: [HL_PRE], post_tags: [HL_POST], pre_tag: HL_PRE, post_tag: HL_POST, fields: f };
180	}
181	
182	function stripMarkers(s) {
183	  return s.split(HL_PRE).join('').split(HL_POST).join('');
184	}
185	
186	/**
187	 * A highlight fragment → children for `h()`: plain strings and <mark> nodes.
188	 * `tags: 'em'` accepts the engine's default `<em>…</em>` wrapping for
189	 * responses we did not shape — the two tags are matched LITERALLY and
190	 * everything else, including any other `<…>`, stays text.
191	 */
192	export function highlightChildren(fragment, { tags = 'markers' } = {}) {
193	  const text = fragment == null ? '' : String(fragment);
194	  const [pre, post] = tags === 'em' ? ['<em>', '</em>'] : [HL_PRE, HL_POST];
195	  const out = [];
196	  let i = 0;
197	  while (i < text.length) {
198	    const s = text.indexOf(pre, i);
199	    if (s < 0) break;
200	    const e = text.indexOf(post, s + pre.length);
201	    if (e < 0) break;
202	    if (s > i) out.push(text.slice(i, s));
203	    const inner = stripMarkers(text.slice(s + pre.length, e));
204	    if (inner) out.push(h('mark', null, inner));
205	    i = e + post.length;
206	  }
207	  if (i < text.length) out.push(text.slice(i));
208	  return out.map((x) => (typeof x === 'string' ? stripMarkers(x) : x)).filter((x) => x !== '');
209	}
210	
211	// ----- mount ----------------------------------------------------------
212	
213	function build(node, doc) {
214	  if (typeof node === 'string') return doc.createTextNode(node);
215	  if (!isNode(node)) return doc.createTextNode('');
216	  // Re-validate at the DOM boundary: a node object that did not come from
217	  // h() (deserialised, hand-built) gets the same checks.
218	  if (!TAGS.has(node.tag)) throw new Error(`safe-dom: tag <${node.tag}> is not allowed`);
219	  const el = doc.createElement(node.tag);
220	  for (const [k, v] of Object.entries(node.attrs || {})) {
221	    if (!attrAllowed(k)) throw new Error(`safe-dom: attribute "${k}" is not allowed`);
222	    if (k === 'href') {
223	      const ok = safeHref(v);
224	      if (ok != null) el.setAttribute('href', ok);
225	      continue;
226	    }
227	    el.setAttribute(k, String(v));
228	  }
229	  for (const c of node.children || []) el.appendChild(build(c, doc));
230	  return el;
231	}
232	
233	/**
234	 * Replace `container`'s children with the given node(s). The container is
235	 * emptied with replaceChildren — never by assigning markup.
236	 */
237	export function mount(container, nodes) {
238	  if (!container) return;
239	  const doc = container.ownerDocument;
240	  const frag = doc.createDocumentFragment();
241	  const list = Array.isArray(nodes) ? nodes : [nodes];
242	  for (const n of list) {
243	    if (n == null || n === false || n === '') continue;
244	    frag.appendChild(build(n, doc));
245	  }
246	  container.replaceChildren(frag);
247	}
