1	// ============================================================
2	// XERJ.ai — Text primitives
3	// Every component is a pure function returning an HTML string.
4	// No state, no events, no DOM access. See UX_BOOK.md §3.
5	// ============================================================
6	
7	/** Escape user text for safe interpolation into template strings. */
8	export const esc = (s) =>
9	  String(s ?? '').replace(/[&<>"']/g, (c) => ({
10	    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
11	  }[c]));
12	
13	/** Compact number formatter (4.82M, 12.3K, 0.83). */
14	const nf = new Intl.NumberFormat('en', { notation: 'compact', maximumFractionDigits: 2 });
15	export const fmt = (v, { decimals } = {}) => {
16	  if (v == null || Number.isNaN(v)) return '—';
17	  if (decimals != null) return Number(v).toFixed(decimals);
18	  // Exact integers stay integers — a count of 4 must never read "4.0".
19	  if (Number.isInteger(v) && Math.abs(v) < 10_000) return new Intl.NumberFormat('en').format(v);
20	  if (Math.abs(v) < 1) return Number(v).toFixed(2);
21	  if (Math.abs(v) < 100) return Number(v).toFixed(1);
22	  return nf.format(v);
23	};
24	
25	/** Pad an integer string to a fixed width with thin spaces (looks tabular). */
26	export const num = (v) => new Intl.NumberFormat('en').format(v);
27	
28	// ----- Eyebrow / headings ------------------------------------
29	
30	/** Small-caps eyebrow label. The ONLY way to title a panel. */
31	export const Key = (text) => `<div class="key">${esc(text)}</div>`;
32	
33	/** `role` ∈ 'scene' | 'section'. Scene is once per view. */
34	export const H = (role, text) => {
35	  const cls = role === 'scene' ? 'h-scene' : 'h-section';
36	  const tag = role === 'scene' ? 'h1' : 'h2';
37	  return `<${tag} class="${cls}">${esc(text)}</${tag}>`;
38	};
39	
40	// ----- Delta indicator ---------------------------------------
41	
42	/**
43	 * `▲ 12.3%` / `▼ 0.12%` — standalone delta.
44	 * `good: 'up' | 'down' | null` — which direction lights the accent.
45	 * If `good` is null, delta is always muted (neutral).
46	 */
47	export const Change = (pct, { good = 'up', unit = '%', fractionDigits = 1 } = {}) => {
48	  if (pct == null || Number.isNaN(pct)) return '';
49	  const up = pct >= 0;
50	  const arrow = up ? '▲' : '▼';
51	  const abs = Math.abs(pct).toFixed(fractionDigits);
52	  let klass = 'meh';
53	  if (good === 'up') klass = up ? 'good' : 'bad';
54	  else if (good === 'down') klass = up ? 'bad' : 'good';
55	  return `<span class="delta ${klass}">${arrow} ${abs}${esc(unit)}</span>`;
56	};
57	
58	// ----- Headline metric ---------------------------------------
59	
60	/**
61	 * Num — the point of every panel.
62	 *   value:     string or number (preformatted is fine)
63	 *   unit:      short unit like 'events', 'e/s', '%', 'ms'
64	 *   spark:     optional Spark(...) string rendered to the right
65	 *   delta:     signed percent, rendered with Change
66	 *   deltaGood: 'up' | 'down' | null — which direction is "good"
67	 *   hint:      small mono hint rendered below ('at 14:23', etc.)
68	 *   emphasis:  true → 96/56px display + accent; false → 32px ink
69	 */
70	export const Num = ({
71	  value,
72	  unit = '',
73	  spark = '',
74	  delta = null,
75	  deltaGood = 'up',
76	  hint = '',
77	  emphasis = true,
78	} = {}) => {
79	  const valCls = emphasis ? 'num-big accent' : 'num-md';
80	  const unitSpan = unit ? `<span class="num-unit">${esc(unit)}</span>` : '';
81	  const deltaPart = delta != null ? Change(delta, { good: deltaGood }) : '';
82	  const hintPart = hint
83	    ? `<span class="hint">${esc(hint)}</span>`
84	    : '';
85	  const foot = (deltaPart || hintPart)
86	    ? `<div class="row-flex" style="margin-top:10px;">${deltaPart}${hintPart}</div>`
87	    : '';
88	  return `
89	  <div class="stack">
90	    <div class="row-flex">
91	      <div class="${valCls}">${esc(value)}${unitSpan}</div>
92	      ${spark}
93	    </div>
94	    ${foot}
95	  </div>`;
96	};
97	
98	// ----- Horizontal-bar row (one line of a TopN) ---------------
99	
100	/**
101	 * A single ranked row. Use `TopN` to render lists; this is exported so you
102	 * can hand-build a row in custom panels.
103	 */
104	export const HBar = ({ label, value, pct, frac, barWidth = 200 }) => {
105	  const f = Math.max(0, Math.min(1, frac ?? 0));
106	  const x = (f * barWidth).toFixed(1);
107	  return `
108	  <div class="row">
109	    <div class="row__label">${esc(label)}</div>
110	    <div class="row__val">${esc(value)}</div>
111	    <div class="row__bar">
112	      <svg class="chart" height="6" viewBox="0 0 ${barWidth} 6" preserveAspectRatio="none">
113	        <line x1="0" y1="5" x2="${x}" y2="5" stroke="currentColor" stroke-width="1"/>
114	      </svg>
115	    </div>
116	    <div class="row__pct">${pct != null ? esc(pct) : ''}</div>
117	  </div>`;
118	};
119	
120	// ----- Inline key/value used in scene kicker ----------------
121	
122	export const Kv = (k, v) =>
123	  `<span class="mono"><span class="faint">${esc(k)}</span> ${esc(v)}</span>`;
