1	// ============================================================
2	// XERJ Console — Reader view (the one stateful piece)
3	//
4	// Search box · result list · the open record · the records linked to it.
5	// Used unchanged by the operator shell (app.js, section READER) and by the
6	// guest shell (guest-app.js); what differs is the `api` it is given
7	// (data/reader-api.js over the console or the guest transport).
8	//
9	// All DOM goes through ux/safe-dom.js#mount. This file holds no markup
10	// strings and calls no HTML-parsing API: record data only ever becomes text
11	// nodes and inert attribute values. Navigation is by ordinary in-app hash
12	// links (`#/reader?index=…&id=…`) — the shell hands the parsed route back
13	// through `setRoute`, so "open this record" needs no click handler at all.
14	// ============================================================
15	
16	import { h, mount } from './safe-dom.js';
17	import { renderResultList, renderRecord, renderGraphPanel, readerHref } from './reader-render.js';
18	import { QUERY_TYPES, queryPlaceholder } from '../data/search-body.js';
19	import { FATAL_KINDS } from '../data/reader-api.js';
20	
21	/** `#/reader?index=a&id=b&brain=c` → { index, id, brain } (strings or null). */
22	export function parseReaderRoute(hash) {
23	  const raw = String(hash || '');
24	  const qi = raw.indexOf('?');
25	  const qs = new URLSearchParams(qi >= 0 ? raw.slice(qi + 1) : '');
26	  const get = (k) => { const v = qs.get(k); return v == null || v === '' ? null : v; };
27	  return { index: get('index'), id: get('id'), brain: get('brain') };
28	}
29	
30	/**
31	 * What the view keeps of `reader-api.js#fetchRelated`'s answer. EVERYTHING it
32	 * returned, with the list defaults the renderer relies on — the first version
33	 * copied four named keys and so dropped the join's `truncated` flag on the
34	 * floor (PR #945 review): the data layer knew the attachment list was
35	 * incomplete and the page never said so.
36	 */
37	export function relatedForView(related, hit) {
38	  const r = related || {};
39	  const isFile = !!(hit && hit._source && hit._source.ax_locator === 'file');
40	  return {
41	    ...r,
42	    attachments: r.attachments || [],
43	    parent: r.parent || null,
44	    fileRecord: r.fileRecord || null,
45	    siblings: r.siblings || (isFile ? [] : undefined),
46	    siblingsTruncated: !!r.siblingsTruncated,
47	  };
48	}
49	
50	/** Results per page of the list, and the most SHOW MORE will ever ask for. */
51	export const PAGE_SIZE = 25;
52	export const MAX_SHOWN = 200;
53	
54	export class ReaderView {
55	  /**
56	   * opts.api       data/reader-api.js#makeReaderApi(transport)
57	   * opts.indices   () => string[]   indices the viewer may pick from
58	   * opts.guest     boolean
59	   * opts.onFatal   (kind) => void   a guest's key stopped working / expired
60	   * opts.onStatus  (status) => void optional: { kind, label } for a shell pill
61	   */
62	  constructor(opts) {
63	    this.api = opts.api;
64	    this.indicesFn = opts.indices || (() => []);
65	    this.guest = !!opts.guest;
66	    this.onFatal = opts.onFatal || (() => {});
67	    const report = opts.onStatus || (() => {});
68	    /** The last status this view reported — the shell re-reads it when it
69	     *  repaints around us without a new search having run. */
70	    this.lastStatus = null;
71	    this.onStatus = (st) => { this.lastStatus = st; report(st); };
72	    this.root = null;
73	    this.slots = null;
74	    this.seq = 0;
75	    this.searchSeq = 0;
76	    this.abort = null;
77	    this.searchAbort = null;
78	    this.s = {
79	      index: null, id: null, brain: null, brains: [], brainHint: null,
80	      q: '', type: 'match',
81	      field: null,           // a sample query's own field (cleared by the next typed search)
82	      size: PAGE_SIZE,
83	      result: null,          // { hits, total, took, error, hint, pending }
84	      hit: null, recordError: null, recordKind: null, loading: false,
85	      related: {},           // { attachments, parent }
86	      graph: { status: 'idle' },
87	    };
88	    this._onKey = (e) => this.handleKey(e);
89	    this._onChange = (e) => this.handleChange(e);
90	    this._onClick = (e) => this.handleClick(e);
91	  }
92	
93	  // ----- routing -------------------------------------------------------
94	
95	  /** Apply a parsed route. Loads only what changed. */
96	  setRoute({ index, id, brain } = {}) {
97	    const allowed = this.indicesFn();
98	    let idx = index;
99	    // A guest can only ever be on one of the share's indices; an index from
100	    // the URL that is not among them is ignored, not requested.
101	    if (this.guest && idx && !allowed.includes(idx)) idx = null;
102	    if (!idx) idx = this.s.index && (!this.guest || allowed.includes(this.s.index)) ? this.s.index : (allowed[0] || null);
103	    const indexChanged = idx !== this.s.index;
104	    const idChanged = (id || null) !== this.s.id;
105	    const hint = this.guest ? null : (brain || null);
106	    const hintChanged = hint !== this.s.brainHint;
107	    this.s.index = idx;
108	    this.s.brainHint = hint;
109	    this.s.id = id || null;
110	    if (indexChanged) { this.s.result = null; this.s.hit = null; this.s.size = PAGE_SIZE; }
111	    // No index at all (an empty engine): there is nothing to load, and the
112	    // shell's status pill must not sit on "LOADING…" forever waiting for a
113	    // search that will never run (PR #945 review).
114	    if (!idx) this.onStatus({ kind: 'live', label: this.guest ? 'NOTHING SHARED' : 'LIVE · NOTHING INDEXED' });
115	    // Coming back to a view whose last load FAILED asks again (a refused or
116	    // unreachable engine may have recovered). A record the engine answered
117	    // "no such id" for is not re-asked on every repaint.
118	    const searchFailed = !!(this.s.result && this.s.result.error);
119	    const recordFailed = !!(this.s.id && !this.s.hit && !this.s.loading && this.s.recordKind !== 'not-found');
120	    if (idx && (indexChanged || !this.s.result || searchFailed)) this.runSearch();
121	    if (indexChanged || idChanged || recordFailed) this.loadRecord();
122	    // Only `&brain=` changed: the record stands, the graph half is re-asked
123	    // with the new hint (PR #945 review: it used to keep the old brain's answer).
124	    else if (hintChanged && this.s.hit) this.reloadGraph();
125	    this.paint();
126	  }
127	
128	  // ----- data ----------------------------------------------------------
129	
130	  fatal(kind) {
131	    if (this.guest && FATAL_KINDS.has(kind)) { this.onFatal(kind); return true; }
132	    return false;
133	  }
134	
135	  async runSearch() {
136	    const index = this.s.index;
137	    if (!index) return;
138	    if (this.searchAbort) this.searchAbort.abort();
139	    const ac = this.searchAbort = new AbortController();
140	    const seq = ++this.searchSeq;
141	    // SHOW MORE keeps the list on screen while the longer one loads.
142	    const keep = this.s.size > PAGE_SIZE && this.s.result && !this.s.result.error ? this.s.result.hits : [];
143	    this.s.result = { hits: keep, total: keep.length ? this.s.result.total : 0, pending: true };
144	    this.paintList();
145	    let r;
146	    try { r = await this.api.search(index, { q: this.s.q, type: this.s.type, size: this.s.size, field: this.s.field }, ac.signal); } catch { return; }
147	    if (seq !== this.searchSeq) return;
148	    if (this.fatal(r.kind)) return;
149	    this.s.result = r;
150	    this.onStatus(r.error ? { kind: 'live-error', label: `READER: ${r.error}` } : { kind: 'live', label: `LIVE · ${index}` });
151	    this.paintList();
152	  }
153	
154	  async loadRecord() {
155	    if (this.abort) this.abort.abort();
156	    const ac = this.abort = new AbortController();
157	    const seq = ++this.seq;
158	    const { index, id } = this.s;
159	    this.s.hit = null; this.s.recordError = null; this.s.recordKind = null; this.s.related = {}; this.s.graph = { status: 'idle' };
160	    if (!index || !id) { this.s.loading = false; this.paintRecord(); this.paintGraph(); return; }
161	    this.s.loading = true;
162	    this.paintRecord(); this.paintGraph();
163	    try {
164	      const rec = await this.api.fetchRecord(index, id, ac.signal);
165	      if (seq !== this.seq) return;
166	      if (this.fatal(rec.kind)) return;
167	      this.s.loading = false;
168	      this.s.hit = rec.hit;
169	      this.s.recordError = rec.hit ? null : (rec.error || 'Not found.');
170	      this.s.recordKind = rec.hit ? null : (rec.kind || 'error');
171	      this.paintRecord(); this.paintList();
172	      if (!rec.hit) { this.paintGraph(); return; }
173	
174	      this.s.graph = { status: 'loading' };
175	      this.paintGraph();
176	      const [related, brains] = await Promise.all([
177	        this.api.fetchRelated(rec.hit, ac.signal),
178	        this.api.resolveBrains(index, this.s.brainHint, ac.signal),
179	      ]);
180	      if (seq !== this.seq) return;
181	      if (this.fatal(related.kind)) return;
182	      this.s.related = relatedForView(related, rec.hit);
183	      this.s.brains = brains;
184	      this.s.brain = brains[0] || null;
185	      this.paintRecord();
186	      this.paintGraph();
187	      const graph = await this.api.fetchGraph(brains, rec.hit, related.fileRecord || null, ac.signal);
188	      if (seq !== this.seq) return;
189	      if (graph.kind === 'expired' && this.fatal('expired')) return;
190	      this.s.graph = graph;
191	      this.paintGraph();
192	    } catch { /* aborted: a newer load owns the view */ }
193	  }
194	
195	  /** Re-ask the graph half for the open record (the `&brain=` hint changed). */
196	  async reloadGraph() {
197	    const hit = this.s.hit;
198	    if (!hit) return;
199	    if (this.abort) this.abort.abort();
200	    const ac = this.abort = new AbortController();
201	    const seq = ++this.seq;
202	    this.s.graph = { status: 'loading' };
203	    this.paintGraph();
204	    try {
205	      const brains = await this.api.resolveBrains(this.s.index, this.s.brainHint, ac.signal);
206	      if (seq !== this.seq) return;
207	      this.s.brains = brains;
208	      this.s.brain = brains[0] || null;
209	      this.paintGraph();
210	      const graph = await this.api.fetchGraph(brains, hit, (this.s.related && this.s.related.fileRecord) || null, ac.signal);
211	      if (seq !== this.seq) return;
212	      if (graph.kind === 'expired' && this.fatal('expired')) return;
213	      this.s.graph = graph;
214	      this.paintGraph();
215	    } catch { /* aborted: a newer load owns the view */ }
216	  }
