219	
220	  /** (Re)attach to a container: builds the skeleton and paints every slot
221	   *  from current state. Safe to call after the shell re-rendered around us. */
222	  attach(container) {
223	    this.detach();
224	    this.root = container;
225	    if (!container) return;
226	    const indices = this.indicesFn();
227	    mount(container, h('div', { class: 'rd-root' },
228	      h('div', { class: 'rd-search' },
229	        h('input', { type: 'search', class: 'rd-q', name: 'rd-q', value: this.s.q, 'aria-label': 'Search this corpus',
230	          placeholder: queryPlaceholder(this.s.type), autocomplete: 'off', spellcheck: 'false' }),
231	        h('select', { class: 'rd-type', name: 'rd-type', 'aria-label': 'Query type' },
232	          QUERY_TYPES.map((t) => h('option', { value: t, selected: t === this.s.type }, t.toUpperCase()))),
233	        indices.length > 1
234	          ? h('select', { class: 'rd-index', name: 'rd-index', 'aria-label': 'Index' },
235	            indices.map((i) => h('option', { value: i, selected: i === this.s.index }, i)))
236	          : h('span', { class: 'rd-index-one mono faint' }, this.s.index || '')),
237	      h('div', { class: 'rd-cols' },
238	        h('section', { class: 'rd-col rd-col--list' }, h('div', { class: 'key', 'data-rd-slot': 'list-head' }), h('div', { 'data-rd-slot': 'list' })),
239	        h('section', { class: 'rd-col rd-col--record' }, h('div', { class: 'key' }, 'RECORD'), h('div', { 'data-rd-slot': 'record' }))),
240	      h('section', { class: 'rd-graph' }, h('div', { class: 'key' }, 'LINKED RECORDS · FROM THE BRAIN'), h('div', { 'data-rd-slot': 'graph' }))));
241	    const slot = (n) => container.querySelector(`[data-rd-slot="${n}"]`);
242	    this.slots = { listHead: slot('list-head'), list: slot('list'), record: slot('record'), graph: slot('graph') };
243	    container.addEventListener('keydown', this._onKey);
244	    container.addEventListener('change', this._onChange);
245	    container.addEventListener('click', this._onClick);
246	    this.paint();
247	  }
