249	  detach() {
250	    if (this.root) {
251	      this.root.removeEventListener('keydown', this._onKey);
252	      this.root.removeEventListener('change', this._onChange);
253	      this.root.removeEventListener('click', this._onClick);
254	    }
255	    this.root = null; this.slots = null;
256	  }
257	
258	  paint() { this.paintIndex(); this.paintList(); this.paintRecord(); this.paintGraph(); }
259	
260	  /** The index label / picker beside the search box follows the route
261	   *  (attach() renders it before setRoute() has set the index). */
262	  paintIndex() {
263	    if (!this.root) return;
264	    const one = this.root.querySelector('.rd-index-one');
265	    if (one) mount(one, this.s.index || '');
266	    const sel = this.root.querySelector('.rd-index');
267	    if (sel && this.s.index && sel.value !== this.s.index) sel.value = this.s.index;
268	  }
269	
270	  paintList() {
271	    if (!this.slots) return;
272	    const r = this.s.result;
273	    const hits = (r && r.hits) || [];
274	    let head = 'RESULTS';
275	    let empty;
276	    let more = null;
277	    if (!this.s.index) empty = this.guest ? 'Nothing is shared.' : 'Nothing is indexed yet. Run: xerj brain <folder>';
278	    else if (!r || (r.pending && !hits.length)) { head = 'SEARCHING…'; empty = 'Searching…'; }
279	    else if (r.error) { head = 'SEARCH FAILED'; empty = `Search failed: ${r.error}. Nothing is shown in its place.`; }
280	    else if (r.hint) { head = 'NOT SEARCHED'; empty = r.hint; }
281	    else {
282	      head = `${r.total} RESULT${r.total === 1 ? '' : 'S'}${hits.length < r.total ? ` · SHOWING ${hits.length}` : ''} · CLICK TO OPEN`;
283	      empty = (this.s.q || '').trim() ? 'No matches. Try a broader query or another query type.' : `No records in ${this.s.index}.`;
284	      if (hits.length < r.total) {
285	        more = r.pending ? h('div', { class: 'rd-more faint mono' }, 'Loading more…')
286	          : hits.length < MAX_SHOWN
287	            ? h('button', { class: 'text-btn rd-more', type: 'button', 'data-rd-more': '1' }, `SHOW ${Math.min(PAGE_SIZE, r.total - hits.length, MAX_SHOWN - hits.length)} MORE`)
288	            : h('div', { class: 'rd-more faint mono' }, `The list stops at the top ${MAX_SHOWN} of ${r.total}. Narrow the query to see the rest.`);
289	      }
290	    }
291	    mount(this.slots.listHead, head);
292	    mount(this.slots.list, [renderResultList(hits, { selectedId: this.s.id, brain: this.s.brainHint, emptyText: empty }), more]);
293	  }
294	
295	  paintRecord() {
296	    if (!this.slots) return;
297	    const s = this.s;
298	    mount(this.slots.record, s.hit
299	      ? renderRecord(s.hit, { related: s.related, brain: s.brainHint })
300	      : renderRecord(null, { emptyText: s.loading ? 'Loading…' : (s.recordError || undefined) }));
301	  }
302	
303	  paintGraph() {
304	    if (!this.slots) return;
305	    const s = this.s;
306	    mount(this.slots.graph, renderGraphPanel(s.hit
307	      ? { brain: s.brain, brains: s.brains, ...s.graph, index: s.hit._index, guest: this.guest }
308	      : { status: 'idle' }));
309	  }
