311	  // ----- events --------------------------------------------------------
312	
313	  handleKey(e) {
314	    const t = e.target;
315	    if (e.key !== 'Enter' || !t || !t.classList || !t.classList.contains('rd-q')) return;
316	    e.preventDefault();
317	    this.s.q = String(t.value || '');
318	    this.s.field = null;       // a typed search runs over the Reader's own fields
319	    this.s.size = PAGE_SIZE;
320	    this.runSearch();
321	  }
322	
323	  handleClick(e) {
324	    const t = e.target;
325	    const more = t && t.closest ? t.closest('[data-rd-more]') : null;
326	    if (!more) return;
327	    e.preventDefault();
328	    this.s.size = Math.min(MAX_SHOWN, this.s.size + PAGE_SIZE);
329	    this.runSearch();
330	  }
331	
332	  handleChange(e) {
333	    const t = e.target;
334	    if (!t || !t.classList) return;
335	    if (t.classList.contains('rd-type')) {
336	      if (QUERY_TYPES.includes(t.value)) {
337	        // Run what is IN THE BOX, not the last submitted query: a person who
338	        // typed a new query and then picked a type saw results for the old one
339	        // under the new text (PR #945 review).
340	        const box = this.root && this.root.querySelector('.rd-q');
341	        if (box) { this.s.q = String(box.value || ''); box.setAttribute('placeholder', queryPlaceholder(t.value)); }
342	        this.s.type = t.value;
343	        this.s.field = null;
344	        this.s.size = PAGE_SIZE;
345	        this.runSearch();
346	      }
347	    } else if (t.classList.contains('rd-index')) {
348	      const win = this.root && this.root.ownerDocument.defaultView;
349	      if (win && this.indicesFn().includes(t.value)) win.location.hash = readerHref({ index: t.value, brain: this.s.brainHint });
350	    }
351	  }
352	
353	  /** Run a query chosen elsewhere (a corpus card's sample query). `field` is
354	   *  the field the sample was written for; it is searched too. */
355	  setQuery({ q, type, field }) {
356	    this.s.q = String(q || '');
357	    if (QUERY_TYPES.includes(type)) this.s.type = type;
358	    this.s.field = typeof field === 'string' && field ? field : null;
359	    this.s.size = PAGE_SIZE;
360	    this.s.result = null;
361	  }
362	}
