1	// ============================================================
2	// XERJ Console — Reader rendering (pure)
3	//
4	// One record in, a node tree out (ux/safe-dom.js). The reader opens ANY
5	// record `xerj autoindex` / `xerj brain` wrote and renders it by SHAPE,
6	// detected from the record's own fields (the autoindex extractors —
7	// engine/crates/xerj-autoindex/src/extract/ — are the contract):
8	//
9	//   email        email_subject / email_from / email_to / email_cc / email_date /
10	//                email_message_id / email_in_reply_to / body   (extract/eml.rs)
11	//   attachment   attachment_name / attachment_content_type / attachment_bytes,
12	//                plus the parent's email_* headers and (for PDFs) page + body
13	//   pdf          page + body + title                          (extract/pdf.rs)
14	//   code-symbol  name / kind / line / language / path / code  (extract/code.rs)
15	//   code-file    language / defs / symbols[]                  (extract/code.rs)
16	//   note         title / body / ax_path  — markdown, docx, text, html
17	//   file         ax_locator = "file" and no body — the one record autoindex
18	//                writes per FILE. It carries no text of its own; it is what
19	//                the file-level graph edges (same_dir, mdlink, pathcite, href)
20	//                point at, so it lists the records that came out of the file.
21	//   generic      anything else: the pretty-printed _source
22	//
23	// Plus the knowledge graph around it: `GET /_graph/{brain}/ego` edges grouped
24	// by edge type, each neighbour a link that opens in this same reader.
25	//
26	// SECURITY. A record is untrusted input: an .eml can carry `<script>` in its
27	// subject, an attachment can be NAMED `"><img src=x onerror=…>.pdf`, a body
28	// can hold `javascript:` URLs, a graph node title is whatever the linked file
29	// said. Nothing here produces markup. Every function returns safe-dom nodes,
30	// in which a document string can only ever be a TEXT child or an inert
31	// attribute value, and the only href is an in-app hash route built by
32	// `readerHref`. Email HTML is never rendered: the extractor indexes the text
33	// part, and that text is shown as text. URLs inside a document are shown,
34	// not linked. No DOM, no fetch: testable under node.
35	// ============================================================
36	
37	import { h, highlightChildren, HL_PRE } from './safe-dom.js';
38	
39	// Vector / passage plumbing the reader never shows (it is huge and meaningless
40	// to a person); counted, never silently dropped.
41	const HIDDEN_FIELD = /(_vector|_vector_chunks|_chunks)$|^__xerj_passage_meta__/;
42	
43	export const SHAPES = ['email', 'attachment', 'pdf', 'code-symbol', 'code-file', 'note', 'file', 'generic'];
44	
45	/** Which renderer a record gets. Order matters: an attachment record also
46	 *  carries its parent's email headers, so it is tested first. */
47	export function detectShape(src) {
48	  const s = src && typeof src === 'object' ? src : {};
49	  const has = (k) => s[k] != null && s[k] !== '';
50	  if (has('attachment_name')) return 'attachment';
51	  if (has('email_subject') || has('email_from') || has('email_message_id')) return 'email';
52	  if (typeof s.code === 'string' && has('name') && has('language')) return 'code-symbol';
53	  if (has('language') && (typeof s.defs === 'string' || Array.isArray(s.symbols))) return 'code-file';
54	  if (has('page') && Number.isFinite(Number(s.page)) && typeof s.body === 'string') return 'pdf';
55	  if (typeof s.body === 'string' || typeof s.text === 'string') return 'note';
56	  if (s.ax_locator === 'file' && has('ax_file')) return 'file';
57	  return 'generic';
58	}
59	
60	/** Coerce any `_source` value to display text. Objects/arrays are JSON, so a
61	 *  multi-valued header (`email_to: [a, b]`) reads as a list, not [object]. */
62	export function str(v) {
63	  if (v == null) return '';
64	  if (typeof v === 'string') return v;
65	  if (typeof v === 'number' || typeof v === 'boolean') return String(v);
66	  if (Array.isArray(v)) return v.map(str).filter(Boolean).join(', ');
67	  try { return JSON.stringify(v); } catch { return ''; }
68	}
69	
70	/** A one-line title for a record, by shape. Never the raw id unless nothing
71	 *  better exists. */
72	export function recordTitle(src, id) {
73	  const s = src && typeof src === 'object' ? src : {};
74	  switch (detectShape(s)) {
75	    case 'attachment':  return str(s.attachment_name);
76	    case 'email':       return str(s.email_subject) || '(no subject)';
77	    case 'code-symbol': return `${s.kind ? str(s.kind) + ' ' : ''}${str(s.name)}`;
78	    case 'code-file':   return str(s.title || s.path || s.ax_path || id);
79	    case 'pdf':         return `${str(s.title || s.ax_path) || 'document'} · p${str(s.page)}`;
80	    case 'note':        return str(s.title || s.ax_path || s.path || id);
81	    case 'file':        return str(s.ax_path || s.title || id);
82	    default:            return str(s.title || s.name || id);
83	  }
84	}
85	
86	/** Short, human badge for the result list. */
87	export function shapeBadge(shape, src) {
88	  const s = src && typeof src === 'object' ? src : {};
89	  switch (shape) {
90	    case 'attachment':  return s.page != null ? `PDF · p${str(s.page)}` : (str(s.attachment_content_type) || 'attachment').split('/').pop().toUpperCase();
91	    case 'email':       return 'EMAIL';
92	    case 'code-symbol': return (str(s.kind) || 'symbol').toUpperCase();
93	    case 'code-file':   return (str(s.language) || 'code').toUpperCase();
94	    case 'pdf':         return `PDF · p${str(s.page)}`;
95	    case 'note':        return (str(s.ax_format) || 'note').toUpperCase();
96	    case 'file':        return `FILE${s.ax_format ? ' · ' + str(s.ax_format).toUpperCase() : ''}`;
97	    default:            return (str(s.ax_format) || 'record').toUpperCase();
98	  }
99	}
100	
101	/** The reader deep link for a record — always an in-app hash route. Values
102	 *  go through URLSearchParams, so an id cannot break out of the query. */
103	export function readerHref({ index, id, brain } = {}) {
104	  const qs = new URLSearchParams();
105	  if (index) qs.set('index', String(index));
106	  if (id) qs.set('id', String(id));
107	  if (brain) qs.set('brain', String(brain));
108	  return `#/reader?${qs.toString()}`;
109	}
110	
111	function fromName(v) {
112	  const s = str(v);
113	  return s.replace(/\s*<[^>]*>\s*$/, '').trim() || s;
114	}
115	function shortDate(v) {
116	  const s = str(v);
117	  const m = s.match(/(\d{4}-\d{2}-\d{2})/);
118	  return m ? m[1] : s.slice(0, 24);
119	}
120	function snippet(src) {
121	  const s = src || {};
122	  const t = s.body || s.text || s.code || s.defs || s.email_subject || '';
123	  return str(t).replace(/\s+/g, ' ').slice(0, 180);
124	}
125	export function fmtBytes(b) {
126	  const n = Number(b);
127	  if (b == null || b === '' || !Number.isFinite(n)) return '';
128	  if (n < 1024) return `${n} B`;
129	  if (n < 1048576) return `${(n / 1024).toFixed(1)} KB`;
130	  return `${(n / 1048576).toFixed(1)} MB`;
131	}
132	
133	// ----- result list ---------------------------------------------------
134	
135	/** Highlight fragments for a hit → nodes, or null when the engine sent none. */
136	function highlightBlock(hit) {
137	  const hl = hit && hit.highlight;
138	  if (!hl || typeof hl !== 'object') return null;
139	  const frags = [];
140	  for (const v of Object.values(hl)) {
141	    for (const f of Array.isArray(v) ? v : [v]) {
142	      if (typeof f === 'string' && f) frags.push(f);
143	      if (frags.length >= 2) break;
144	    }
145	    if (frags.length >= 2) break;
146	  }
147	  if (!frags.length) return null;
148	  // Our markers when the engine honoured them; otherwise its default
149	  // `<em>…</em>`, matched literally. Either way the fragment becomes text
150	  // nodes and <mark> elements — it is never parsed.
151	  return frags.map((f) => h('span', { class: 'rd-card__frag' },
152	    highlightChildren(f.replace(/\s+/g, ' '), { tags: f.includes(HL_PRE) ? 'markers' : 'em' })));
153	}
154	
155	/** One clickable result card. `selectedId` marks the open record. */
156	export function renderResultCard(hit, { selectedId, brain } = {}) {
157	  const s = (hit && hit._source && typeof hit._source === 'object') ? hit._source : {};
158	  const shape = detectShape(s);
159	  const score = Number(hit._score);
160	  const meta = shape === 'email' || shape === 'attachment'
161	    ? `${fromName(s.email_from)}${s.email_date ? ' · ' + shortDate(s.email_date) : ''}`
162	    : str(s.ax_path || s.path || hit._index);
163	  return h('a', {
164	    class: `rd-card${hit._id === selectedId ? ' sel' : ''}`,
165	    href: readerHref({ index: hit._index, id: hit._id, brain }),
166	    'data-reader-open': str(hit._id),
167	    'data-reader-index': str(hit._index),
168	  },
169	    h('div', { class: 'rd-card__top' },
170	      h('span', { class: `rd-badge rd-badge--${shape}` }, shapeBadge(shape, s)),
171	      h('span', { class: 'rd-card__title' }, recordTitle(s, hit._id)),
172	      Number.isFinite(score) && hit._score != null ? h('span', { class: 'rd-card__score' }, score.toFixed(2)) : null),
173	    h('div', { class: 'rd-card__meta' }, meta),
174	    h('div', { class: 'rd-card__snip' }, highlightBlock(hit) || snippet(s)));
175	}
176	
177	/** The whole list, or an honest empty state. */
178	export function renderResultList(hits, { selectedId, brain, emptyText } = {}) {
179	  if (!hits || !hits.length) return h('div', { class: 'rd-empty' }, emptyText || 'No records. Search above, or open one from Discover.');
180	  return h('div', { class: 'rd-list' }, hits.map((x) => renderResultCard(x, { selectedId, brain })));
181	}
182	
183	// ----- the record ----------------------------------------------------
184	
185	const hdr = (k, v) => {
186	  const t = str(v);
187	  return t === '' ? null : h('div', { class: 'rd-hdr' }, h('span', { class: 'rd-k' }, k), h('span', { class: 'rd-v' }, t));
188	};
189	
190	function relatedLink(rec, brain, name, meta) {
191	  return h('a', {
192	    class: 'rd-att',
193	    href: readerHref({ index: rec._index, id: rec._id, brain }),
194	    'data-reader-open': str(rec._id),
195	    'data-reader-index': str(rec._index),
196	  }, h('span', { class: 'rd-att__name' }, name), h('span', { class: 'rd-att__meta' }, meta));
197	}
198	
199	function attachmentsBlock(related, brain) {
200	  const attachments = related.attachments;
201	  if (attachments === undefined) return h('div', { class: 'rd-sub faint' }, 'attachments: looking…');
202	  // A join that FAILED is not "no attachments".
203	  if (related.attachmentsError) {
204	    return h('div', { class: 'rd-sub faint', 'data-rd-block': 'attachments-error' }, `This email's attachments could not be read (${str(related.attachmentsError)}).`);
205	  }
206	  if (!attachments || !attachments.length) return null;
207	  const cut = related.attachmentsTruncated && typeof related.attachmentsTruncated === 'object' ? related.attachmentsTruncated : null;
208	  return h('div', { class: 'rd-sub', 'data-rd-block': 'attachments' },
209	    h('div', { class: 'key' }, `ATTACHMENTS · ${attachments.length}${cut ? '+' : ''}`),
210	    attachments.map((a) => {
211	      const s = a._source || {};
212	      const bits = [str(s.attachment_content_type), fmtBytes(s.attachment_bytes), s.page != null ? `page ${str(s.page)}` : '']
213	        .filter(Boolean).join(' · ');
214	      return relatedLink(a, brain, str(s.attachment_name) || str(a._id), bits);
215	    }),
216	    cut ? h('div', { class: 'rd-honest mono faint', 'data-rd-block': 'attachments-truncated' },
217	      `This list may be incomplete: this email has ${str(cut.total)} attachment records and the first ${str(cut.read)} were read, so an attachment past them is not listed. Open the file record below for the file's records.`) : null);
218	}
219	
220	/** The records that came out of one file (the `file` shape), or — on any
221	 *  other record — a link up to its file. */
222	function siblingsBlock(siblings, brain, truncated, total) {
223	  if (siblings === undefined) return h('div', { class: 'rd-sub faint' }, 'records in this file: looking…');
224	  if (!siblings || !siblings.length) return h('div', { class: 'rd-sub faint' }, 'No other record came out of this file.');
225	  return h('div', { class: 'rd-sub', 'data-rd-block': 'siblings' },
226	    h('div', { class: 'key' }, truncated && Number(total) > siblings.length
227	      ? `RECORDS IN THIS FILE · ${siblings.length} OF ${str(total)} SHOWN`
228	      : `RECORDS IN THIS FILE · ${siblings.length}${truncated ? '+' : ''}`),
229	    siblings.map((r) => {
230	      const rs = r._source || {};
231	      return relatedLink(r, brain, recordTitle(rs, r._id), shapeBadge(detectShape(rs), rs));
232	    }));
233	}
234	
235	function fileBlock(fileRecord, brain) {
236	  if (!fileRecord) return null;
237	  const fs = fileRecord._source || {};
238	  return h('div', { class: 'rd-sub', 'data-rd-block': 'file' },
239	    h('div', { class: 'key' }, 'FROM FILE'),
240	    relatedLink(fileRecord, brain, str(fs.ax_path || fs.title) || str(fileRecord._id), 'every record from this file'));
241	}
242	
243	function parentBlock(parent, brain) {
244	  if (!parent) return null;
245	  const s = parent._source || {};
246	  return h('div', { class: 'rd-sub', 'data-rd-block': 'parent' },
247	    h('div', { class: 'key' }, 'FROM EMAIL'),
248	    relatedLink(parent, brain, str(s.email_subject) || '(no subject)',
249	      `${fromName(s.email_from)}${s.email_date ? ' · ' + shortDate(s.email_date) : ''}`));
250	}
251	
252	/** Body text. Always a text node inside a pre-wrapped block — an HTML email
253	 *  that reached the index as text is displayed as its source, never run. */
