342	/** Human labels for the edge types autoindex's detectors emit — one per
343	 *  `EDGE_TYPE` constant in engine/crates/xerj-autoindex/src/detect/*.rs. Any
344	 *  other type (a hand-written `/_graph/{brain}/link`) shows its raw name. */
345	export const EDGE_LABELS = {
346	  wikilink:    'wiki-links',
347	  mdlink:      'markdown links',
348	  href:        'hyperlinks',
349	  pathcite:    'cites the path of',
350	  cratecite:   'cites the crate of',
351	  sequence:    'next / previous section',
352	  same_dir:    'same folder',
353	  shared_term: 'shares rare terms with',
354	};
355	
356	export function edgeLabel(type) {
357	  const t = str(type);
358	  return Object.prototype.hasOwnProperty.call(EDGE_LABELS, t) ? EDGE_LABELS[t] : (t || 'linked').replace(/_/g, ' ');
359	}
360	
361	/**
362	 * An ego response → neighbours grouped by edge type (groups in first-seen
363	 * order, neighbours by title). Each
364	 * item is the OTHER endpoint of an edge touching `focusId`, hydrated from
365	 * `ego.nodes` when the call asked for `include_nodes`.
366	 */
367	export function groupNeighbors(ego, focusId) {
368	  const groups = new Map();
369	  const nodes = (ego && ego.nodes && typeof ego.nodes === 'object') ? ego.nodes : {};
370	  const seen = new Set();
371	  for (const e of (ego && Array.isArray(ego.edges)) ? ego.edges : []) {
372	    if (!e || (e.src !== focusId && e.dst !== focusId)) continue;
373	    const out = e.src === focusId;
374	    const other = out ? e.dst : e.src;
375	    if (typeof other !== 'string' || !other || other === focusId) continue;
376	    const type = str(e.type) || 'linked';
377	    const key = `${type}\n${other}`;
378	    if (seen.has(key)) continue;
379	    seen.add(key);
380	    const n = Object.prototype.hasOwnProperty.call(nodes, other) && nodes[other] ? nodes[other] : null;
381	    const item = {
382	      id: other,
383	      index: n && typeof n.index === 'string' ? n.index : null,
384	      title: (n && typeof n.title === 'string' && n.title) || (n && typeof n.path === 'string' && n.path) || other,
385	      path: n && typeof n.path === 'string' ? n.path : null,
386	      preview: n && typeof n.preview === 'string' ? n.preview : null,
387	      direction: out ? 'out' : 'in',
388	      hop: e.hop ?? 1,
389	      edgeId: e.edge_id,
390	      weight: e.weight,
391	      hydrated: !!n,
392	    };
393	    if (!groups.has(type)) groups.set(type, { type, label: edgeLabel(type), items: [] });
394	    groups.get(type).items.push(item);
395	  }
396	  // The engine returns edges in no fixed order (two live runs over the same
397	  // corpus listed the same two neighbours both ways round). Sort, so a record's
398	  // panel reads the same every time it is opened.
399	  const out = [...groups.values()];
400	  for (const g of out) g.items.sort((a, b) => String(a.title).localeCompare(String(b.title)) || String(a.id).localeCompare(String(b.id)));
401	  return out;
402	}
