20	const humanCount = (n) => {
21	  if (n == null) return '—';
22	  if (n >= 1e9) return (n / 1e9).toFixed(1) + 'B';
23	  if (n >= 1e6) return (n / 1e6).toFixed(1) + 'M';
24	  if (n >= 1e3) return (n / 1e3).toFixed(0) + 'K';
25	  return String(n);
26	};
27	const humanBytes = (b) => {
28	  if (b == null) return '—';
29	  const u = ['B','KB','MB','GB','TB','PB'];
30	  let v = b, i = 0;
31	  while (v >= 1024 && i < u.length - 1) { v /= 1024; i++; }
32	  return v.toFixed(v < 10 ? 1 : 0) + ' ' + u[i];
33	};
