35	export const dataSection = {
36	  id: 'data',
37	  name: 'Data',
38	  section: 'data',
39	  render: ({ data, time }) => {
40	    const clusters = data.clusters || [];
41	    const indicesByCluster = data.indicesByCluster || {};
42	    const fieldsByIndex = data.fieldsByIndex || {};
43	    const active = data.activeCluster || 'local';
44	    const activeIndices = indicesByCluster[active] || [];
45	    const focusIndex = data.focusIndex || activeIndices[0]?.name;
46	    const fields = fieldsByIndex[focusIndex] || [];
47	    const unreachable = !clusters.length;
48	
49	    return {
50	      title: 'DATA',
51	      kicker: 'CONNECTIONS · INDICES · FIELDS',
52	      meta: [time, 'SOURCES'],
53	      caption: unreachable
54	        ? 'No data source could be read. This page lists only what the engine reports — sign in, or start the node, and reload.'
55	        : 'What the engine actually has: one row per index (documents, on-disk store bytes) and each index\'s mapping. Per-dataset structure, coverage and examples live on CORPUS.',
56	      panels: [
57	
58	        { id: 'clusters', eyebrow: 'CONNECTIONS · CLICK TO SET DEFAULT', cols: 12, type: 'clusters',
59	          render: () => renderClusters(clusters, active),
60	        },
61	
62	        { id: 'indices', eyebrow: `INDICES · ${active.toUpperCase()} · CLICK AN INDEX TO INSPECT FIELDS`, cols: 6, type: 'indices',
63	          render: () => renderIndices(activeIndices, focusIndex),
64	        },
