93	function renderClusters(clusters, active) {
94	  if (!clusters.length) return '<div class="mono faint">No data source readable. Sign in and reload — this page never shows a sample.</div>';
95	  const rows = clusters.map((c) => {
96	    const isActive = c.id === active;
97	    const status = {
98	      green:  `<span class="mono accent">●</span>`,
99	      yellow: `<span class="mono faint">◐</span>`,
100	      red:    `<span class="mono">○</span>`,
101	    }[c.status] || '—';
102	    return `
103	      <button type="button" class="mg-cluster${isActive ? ' mg-cluster-active' : ''}" data-mg-cluster="${esc(c.id)}">
104	        <span class="mg-cluster-status">${status}</span>
105	        <span class="mg-cluster-name mono${isActive ? ' accent' : ''}">${esc(c.name)}</span>
106	        <span class="mg-cluster-url mono faint">${esc(c.url)}</span>
107	        <span class="mg-cluster-stat mono">${humanCount(c.indices)}&nbsp;idx</span>
108	        <span class="mg-cluster-stat mono">${humanCount(c.docs)}&nbsp;docs</span>
109	        <span class="mg-cluster-ver mono faint">${esc(c.version || '')}</span>
110	      </button>`;
111	  }).join('');
112	  return `<div class="mg-clusters">${rows}</div>`;
113	}
114	
115	function renderIndices(indices, focusIndex) {
116	  if (!indices.length) return '<div class="mono faint">No indices on this engine.</div>';
117	  const cols = ['NAME', 'DOCS', 'SIZE', 'SHARDS'];
118	  const headRow = `<div class="mg-idx-row mg-idx-head">${cols.map((c) => `<span>${esc(c)}</span>`).join('')}</div>`;
