1	// ============================================================
2	// XERJ.ai — Table + Markdown primitives
3	// Plain text, no borders, no zebra stripes, no cell backgrounds.
4	// ============================================================
5	
6	import { esc } from './text.js';
7	
8	/**
9	 * Table — borderless tabular data. Replaces Kibana "Data Table".
10	 *
11	 *   columns: ['NAME', 'COUNT', ...]
12	 *   rows:    [[cell, cell, ...], ...]
13	 *   align:   ['left'|'right'|'center', ...] — per column
14	 */
15	export const Table = ({ columns, rows, align = [] } = {}) => {
16	  if (!columns || !columns.length) return '<div class="faint mono">No columns.</div>';
17	  const ta = (i) => align[i] || (i === 0 ? 'left' : 'right');
18	  const cols = columns.length;
19	  const headCells = columns.map((c, i) =>
20	    `<span style="text-align:${ta(i)}">${esc(c)}</span>`
21	  ).join('');
22	  const bodyRows = (rows || []).map((r) => {
23	    const cells = r.map((c, i) =>
24	      `<span style="text-align:${ta(i)}">${esc(c)}</span>`
25	    ).join('');
26	    return `<div class="tbl-row">${cells}</div>`;
27	  }).join('');
28	  return `
29	  <div class="tbl" style="--tbl-cols:${cols};">
30	    <div class="tbl-row tbl-head">${headCells}</div>
31	    ${bodyRows}
32	  </div>`;
33	};
34	
35	/**
36	 * Markdown — very light markdown for annotation panels.
37	 * Supports: **bold**, *italic*, `code`, # heading, ## eyebrow, blank-line paragraphs.
38	 * No HTML injection — everything runs through `esc` first.
39	 */
40	export const Markdown = (text = '') => {
41	  if (!text) return '';
42	  const paragraphs = text.split(/\n\n+/).map((p) => {
43	    const t = p.trim();
44	    if (!t) return '';
45	    if (t.startsWith('# '))  return `<div class="h-section" style="margin-bottom:10px;">${esc(t.slice(2))}</div>`;
46	    if (t.startsWith('## ')) return `<div class="key" style="margin-bottom:8px;">${esc(t.slice(3))}</div>`;
47	    const e = esc(t)
48	      .replace(/\*\*(.+?)\*\*/g, '<strong style="color:var(--z-ink);">$1</strong>')
49	      .replace(/\*(.+?)\*/g, '<em>$1</em>')
50	      .replace(/`([^`]+)`/g, '<span class="mono accent">$1</span>');
51	    return `<p style="max-width:60ch; margin-bottom:10px;">${e}</p>`;
52	  }).filter(Boolean).join('');
53	  return `<div class="md" style="font-family:var(--font-prose); font-size:var(--fs-13); line-height:1.6; color:var(--z-mute);">${paragraphs}</div>`;
54	};
