1	//! Error types for the Xerj Console API surface.
2	//!
3	//! Every handler returns `ConsoleResult<T>`, which `axum` serialises into a
4	//! JSON body with the same envelope as the rest of xerj's HTTP error
5	//! responses (so a Xerj Console 404 looks the same as a `/v1/...` 404 to the SPA).
6	
7	use axum::{
8	    http::StatusCode,
9	    response::{IntoResponse, Response},
10	    Json,
11	};
12	use serde_json::json;
13	
14	#[derive(Debug, thiserror::Error)]
15	pub enum ConsoleApiError {
16	    #[error("not found: {0}")]
17	    NotFound(String),
18	
19	    #[error("conflict: {0}")]
20	    Conflict(String),
21	
22	    /// RFC 6585 §3 — the request must carry a precondition header
23	    /// (`If-Match`) and did not. Distinct from [`Self::Conflict`], which
24	    /// means the precondition was sent but did not match.
25	    #[error("precondition required: {0}")]
26	    PreconditionRequired(String),
27	
28	    #[error("forbidden: {0}")]
29	    Forbidden(String),
30	
31	    #[error("unauthorized: {0}")]
32	    Unauthorized(String),
33	
34	    #[error("bad request: {0}")]
35	    BadRequest(String),
36	
37	    #[error("not implemented: {0}")]
38	    NotImplemented(String),
39	
40	    #[error("rate limited")]
41	    RateLimited,
42	
43	    /// Wraps an underlying engine / I/O failure. The full error message is
44	    /// emitted to tracing; the HTTP body shows a generic 500 to avoid
45	    /// leaking internal paths.
46	    #[error("internal: {0}")]
47	    Internal(String),
48	}
49	
50	pub type ConsoleResult<T> = Result<T, ConsoleApiError>;
51	
52	impl ConsoleApiError {
53	    pub fn status(&self) -> StatusCode {
54	        match self {
55	            Self::NotFound(_) => StatusCode::NOT_FOUND,
56	            Self::Conflict(_) => StatusCode::CONFLICT,
57	            Self::PreconditionRequired(_) => StatusCode::PRECONDITION_REQUIRED,
58	            Self::Forbidden(_) => StatusCode::FORBIDDEN,
59	            Self::Unauthorized(_) => StatusCode::UNAUTHORIZED,
60	            Self::BadRequest(_) => StatusCode::BAD_REQUEST,
61	            Self::NotImplemented(_) => StatusCode::NOT_IMPLEMENTED,
62	            Self::RateLimited => StatusCode::TOO_MANY_REQUESTS,
63	            Self::Internal(_) => StatusCode::INTERNAL_SERVER_ERROR,
64	        }
65	    }
66	
67	    pub fn kind(&self) -> &'static str {
68	        match self {
69	            Self::NotFound(_) => "not_found",
70	            Self::Conflict(_) => "conflict",
71	            Self::PreconditionRequired(_) => "precondition_required",
72	            Self::Forbidden(_) => "forbidden",
73	            Self::Unauthorized(_) => "unauthorized",
74	            Self::BadRequest(_) => "bad_request",
75	            Self::NotImplemented(_) => "not_implemented",
76	            Self::RateLimited => "rate_limited",
77	            Self::Internal(_) => "internal_error",
78	        }
79	    }
80	}
81	
82	impl IntoResponse for ConsoleApiError {
83	    fn into_response(self) -> Response {
84	        let status = self.status();
85	        // Internal errors never leak the message to the client. Everything
86	        // the SPA can act on is in `kind`; the human-readable line is for
87	        // logs only.
88	        let display = if matches!(self, Self::Internal(_)) {
89	            "internal server error".to_string()
90	        } else {
91	            self.to_string()
92	        };
93	
94	        if matches!(self, Self::Internal(ref msg) if !msg.is_empty()) {
95	            tracing::error!(error = %self, "xerj-console internal error");
96	        }
97	
98	        // Emit the API-contract keys (`code`/`message`) alongside the legacy
99	        // (`type`/`reason`) pair. `code` uses the contract vocabulary
100	        // (`conflict|forbidden|not_found|bad_request`, …) via `kind`, so the
101	        // SPA can read the documented shape while older readers still find
102	        // `type`/`reason`. Purely additive — no existing consumer breaks.
103	        let body = json!({
104	            "error": {
105	                "code":    self.kind(),
106	                "message": display,
107	                "type":    self.kind(),
108	                "reason":  display,
109	            }
110	        });
111	
112	        (status, Json(body)).into_response()
113	    }
114	}
115	
116	// Common conversions so handlers can use `?` on engine and serde failures.
117	
118	impl From<xerj_common::XerjError> for ConsoleApiError {
119	    fn from(e: xerj_common::XerjError) -> Self {
120	        // Map the few error categories the Xerj Console surface is likely to surface.
121	        let msg = e.to_string();
122	        let lower = msg.to_lowercase();
123	        if lower.contains("not found") {
124	            Self::NotFound(msg)
125	        } else if lower.contains("already exists") {
126	            Self::Conflict(msg)
127	        } else {
128	            Self::Internal(msg)
129	        }
130	    }
131	}
132	
133	impl From<xerj_engine::EngineError> for ConsoleApiError {
134	    fn from(e: xerj_engine::EngineError) -> Self {
135	        Self::Internal(e.to_string())
136	    }
137	}
138	
139	impl From<serde_json::Error> for ConsoleApiError {
140	    fn from(e: serde_json::Error) -> Self {
141	        Self::BadRequest(format!("invalid json: {e}"))
142	    }
143	}
144	
145	impl From<std::io::Error> for ConsoleApiError {
146	    fn from(e: std::io::Error) -> Self {
147	        Self::Internal(format!("io: {e}"))
148	    }
149	}
