 1	// ============================================================
 2	// XERJ Console — "where was I going?" across the sign-in page
 3	//
 4	// A deep link (`/_xerj-console/#/reader?index=…&id=…` — the link llms.txt
 5	// tells an agent to hand a person) opened without a session is redirected to
 6	// `/login`, which used to drop the hash and land on the Corpus home after
 7	// sign-in: the person had to click the link a second time (PR #945 review).
 8	// boot.js stashes the route here before it redirects; login.html takes it
 9	// back out once the passkey ceremony succeeds.
10	//
11	// Only an in-console hash route is ever kept or returned — `#/` followed by
12	// route characters, no scheme, no whitespace — and it is only ever appended to
13	// `/_xerj-console/`, so it cannot become a redirect anywhere else. It lives in
14	// sessionStorage: this tab, this visit. Pure: storage is passed in.
15	// ============================================================
16	
17	export const NEXT_KEY = 'xerj.next';
18	const ROUTE_RE = /^#\/[A-Za-z0-9/?&=_%.+~*!'()-]*$/;
19	
20	/** `hash` when it is an in-console route worth coming back to, else ''. */
21	export function safeRoute(hash) {
22	  const h = typeof hash === 'string' ? hash : '';
23	  if (h.length < 3 || h.length > 2048 || h.includes('//') || !ROUTE_RE.test(h)) return '';
24	  return h;
25	}
26	
27	/** Remember `hash` for after sign-in. A blocked storage is not an error. */
28	export function stashNext(storage, hash) {
29	  const route = safeRoute(hash);
30	  try {
31	    if (route) storage.setItem(NEXT_KEY, route);
32	    else storage.removeItem(NEXT_KEY);
33	  } catch { /* storage blocked: the person lands on the home page, as before */ }
34	  return route;
35	}
36	
