 90	        let name = path.file_name().and_then(|n| n.to_str()).unwrap_or("");
 91	        if name.starts_with('.') || name == "node_modules" {
 92	            continue;
 93	        }
 94	        let meta = match fs::metadata(&path) {
 95	            Ok(m) => m,
 96	            Err(_) => continue,
 97	        };
 98	        if meta.is_dir() {
 99	            walk(root, &path, out);
100	            continue;
101	        }
102	        if meta.len() > MAX_FILE_BYTES {
103	            println!(
104	                "cargo:warning=xerj-console skipping {} (>{} bytes)",
105	                path.display(),
106	                MAX_FILE_BYTES
107	            );
108	            continue;
109	        }
110	        let ext = path
111	            .extension()
112	            .and_then(|e| e.to_str())
113	            .map(str::to_ascii_lowercase)
114	            .unwrap_or_default();
115	        if !ALLOWED_EXTS.contains(&ext.as_str()) {
