119	        let url_path = rel
120	            .components()
121	            .map(|c| c.as_os_str().to_string_lossy().into_owned())
122	            .collect::<Vec<_>>()
123	            .join("/");
124	        println!("cargo:rerun-if-changed={}", path.display());
125	        out.push((url_path, path));
126	    }
127	}
