137	         //\n\
138	         // (url_path, bytes, content_type) tuples. Order is sorted-by-path\n\
139	         // so the runtime can binary-search by path.\n\
140	         pub static XERJ_CONSOLE_ASSETS: &[(&str, &[u8], &str)] = &["
